-- ----------------------------
-- Table structure for erp_certified_source_birth
-- ----------------------------
DROP TABLE IF EXISTS `erp_certified_source_birth`;
CREATE TABLE `erp_certified_source_birth`  (
  `birth_id` bigint(20) NOT NULL COMMENT '服务端生成出生主键',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建事务租户',
  `material_id` bigint(20) NOT NULL COMMENT '同事务服务端新建物料主键，禁止旧物料补登记',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '新物料原始编码',
  `category_id` bigint(20) NOT NULL COMMENT '创建时分类主键',
  `base_uom_id` bigint(20) NOT NULL COMMENT '已正式确认的根基本单位主键',
  `quantity_scale` tinyint(3) UNSIGNED NOT NULL COMMENT '创建时已核基本单位精度',
  `conversion_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建时正式单位版本',
  `unit_verified_at` datetime(0) NOT NULL COMMENT '创建时单位正式核验时点，不能由客户端出生请求提供',
  `unit_fingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务端完整单位原始事实摘要',
  `warehouse_id` bigint(20) NOT NULL COMMENT '出生明确的仓库主键，不缩小物料全局库存池',
  `area_id` bigint(20) NOT NULL COMMENT '出生明确的库区主键',
  `location_id` bigint(20) NOT NULL COMMENT '出生明确的储位主键',
  `storage_fingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务端完整仓储父链摘要',
  `born_at` datetime(0) NOT NULL COMMENT '与物料插入同事务的数据库时点',
  `actor_id` bigint(20) NOT NULL COMMENT '服务端当前登录操作人',
  `scenario` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '明确本地测试模拟场景，不冒充现场实绩',
  `initial_state` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始出生状态 EMPTY_AT_BIRTH；无记录不是可靠零',
  `birth_fingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务端固定版本出生摘要，不充当完整采购来源摘要',
  PRIMARY KEY (`birth_id`) USING BTREE,
  UNIQUE INDEX `uk_source_birth_material`(`tenant_id`, `material_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '新测试物料初始空范围永久出生事实' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of erp_certified_source_birth
-- ----------------------------

-- ----------------------------
-- Table structure for erp_subcontract_doc
-- ----------------------------
DROP TABLE IF EXISTS `erp_subcontract_doc`;
CREATE TABLE `erp_subcontract_doc`  (
  `doc_id` bigint(20) NOT NULL COMMENT '文件ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `material_id` bigint(20) NOT NULL COMMENT '物料ID',
  `subcontract_id` bigint(20) NULL DEFAULT NULL COMMENT '委外订单ID(NULL=物料级工程文件库)',
  `doc_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件类型: GERBER/PICK_PLACE/BOM_FILE/STENCIL/PROCESS_FILE/OTHER',
  `doc_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件名称',
  `file_oss_id` bigint(20) NOT NULL COMMENT 'OSS文件ID(sys_oss.oss_id)',
  `doc_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件版本',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`doc_id`) USING BTREE,
  INDEX `idx_sc_doc_material`(`tenant_id`, `material_id`) USING BTREE,
  INDEX `idx_sc_doc_subcontract`(`subcontract_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '委外工程文件' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fa_asset
-- ----------------------------
DROP TABLE IF EXISTS `fa_asset`;
CREATE TABLE `fa_asset`  (
  `asset_id` bigint(20) NOT NULL COMMENT '资产ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `asset_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资产编号(自动生成 FA-YYYY-NNNN)',
  `asset_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资产名称',
  `category_id` bigint(20) NOT NULL COMMENT '类别ID',
  `original_value` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '原值',
  `salvage_value` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '净残值(原值×残值率,可手工覆盖)',
  `useful_life` int(11) NOT NULL DEFAULT 120 COMMENT '使用年限(月,随类别带出可改)',
  `depreciation_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '折旧方法(空=随类别)',
  `acquisition_date` date NULL DEFAULT NULL COMMENT '购置日期',
  `in_use_date` date NULL DEFAULT NULL COMMENT '启用日期(开始计提,空=购置日)',
  `location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '存放地点',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'IN_USE' COMMENT '状态 IN_USE-使用中 CWIP-在建 DISPOSED-已处置',
  `cumulative_depreciation` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '累计已计提折旧(随折旧过账更新)',
  `net_book_value` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '账面净值(原值-累计折旧)',
  `version` int(11) NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`asset_id`) USING BTREE,
  UNIQUE INDEX `uk_asset_no`(`asset_no`, `tenant_id`) USING BTREE,
  INDEX `idx_category`(`category_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '固定资产卡片' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fa_asset_category
-- ----------------------------
DROP TABLE IF EXISTS `fa_asset_category`;
CREATE TABLE `fa_asset_category`  (
  `category_id` bigint(20) NOT NULL COMMENT '类别ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `category_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '类别编码',
  `category_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类别名称(如 机器设备/办公设备/运输工具)',
  `depreciation_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STRAIGHT_LINE' COMMENT '折旧方法 STRAIGHT_LINE-直线法 DOUBLE_DECLINING-双倍余额递减 SUM_OF_YEARS-年数总和 MANUAL-手工',
  `useful_life` int(11) NOT NULL DEFAULT 120 COMMENT '预计使用年限(月)',
  `salvage_value_rate` decimal(10, 4) NULL DEFAULT 0.0000 COMMENT '净残值率(0-1,默认0)',
  `debit_account_id` bigint(20) NULL DEFAULT NULL COMMENT '折旧费用科目ID(借,默认查 6602 管理费用)',
  `credit_account_id` bigint(20) NULL DEFAULT NULL COMMENT '累计折旧科目ID(贷,默认查 1602)',
  `disposal_loss_account_id` bigint(20) NULL DEFAULT NULL COMMENT '处置损失科目ID(借,默认查 6711 营业外支出)',
  `disposal_gain_account_id` bigint(20) NULL DEFAULT NULL COMMENT '处置收益科目ID(贷,默认查 6301 营业外收入)',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '状态 0-正常 1-停用',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '显示顺序',
  `version` int(11) NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`category_id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`category_code`, `tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '固定资产类别(折旧政策)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of fa_asset_category
-- ----------------------------

-- ----------------------------
-- Table structure for fa_depreciation
-- ----------------------------
DROP TABLE IF EXISTS `fa_depreciation`;
CREATE TABLE `fa_depreciation`  (
  `depreciation_id` bigint(20) NOT NULL COMMENT '折旧ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `asset_id` bigint(20) NOT NULL COMMENT '资产ID',
  `period_id` bigint(20) NOT NULL COMMENT '期间ID',
  `depreciation_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '本期折旧额',
  `cumulative_depreciation` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '计提后累计折旧',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PLANNED' COMMENT '状态 PLANNED-计划 DONE-已过账',
  `posted_voucher_id` bigint(20) NULL DEFAULT NULL COMMENT '过账凭证ID',
  `posted_voucher_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '过账凭证号',
  `version` int(11) NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`depreciation_id`) USING BTREE,
  UNIQUE INDEX `uk_asset_period`(`asset_id`, `period_id`, `tenant_id`) USING BTREE,
  INDEX `idx_period`(`period_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '固定资产折旧记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fa_disposal
-- ----------------------------
DROP TABLE IF EXISTS `fa_disposal`;
CREATE TABLE `fa_disposal`  (
  `disposal_id` bigint(20) NOT NULL COMMENT '处置ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `asset_id` bigint(20) NOT NULL COMMENT '资产ID',
  `disposal_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型 SALE-出售 SCRAP-报废',
  `disposal_date` date NOT NULL COMMENT '处置日期',
  `disposal_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '处置收入(售价/残值回收)',
  `net_book_value` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '处置时账面净值(原值-累计折旧)',
  `gain_loss` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '处置损益(正=收益 负=损失)',
  `posted_voucher_id` bigint(20) NULL DEFAULT NULL COMMENT '过账凭证ID',
  `posted_voucher_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '过账凭证号',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'POSTED' COMMENT '状态 POSTED-已过账',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `version` int(11) NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`disposal_id`) USING BTREE,
  INDEX `idx_asset`(`asset_id`) USING BTREE,
  INDEX `idx_date`(`disposal_date`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '固定资产处置记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fin_close_log
-- ----------------------------
DROP TABLE IF EXISTS `fin_close_log`;
CREATE TABLE `fin_close_log`  (
  `log_id` bigint(20) NOT NULL COMMENT '日志ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `period_id` bigint(20) NOT NULL COMMENT '期间ID',
  `close_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型 MONTHLY-月结 YEARLY-年结',
  `step` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '步骤 TRIAL_CHECK/CARRY_PL/REVALUATION/REPORT_SNAPSHOT/CLOSE_PERIOD/CARRY_FORWARD',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态 SUCCESS/FAILED',
  `message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '结果/错误信息',
  `operator_id` bigint(20) NULL DEFAULT NULL COMMENT '操作人',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`log_id`) USING BTREE,
  INDEX `idx_period`(`period_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '期末关账执行日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fin_receipt
-- ----------------------------
DROP TABLE IF EXISTS `fin_receipt`;
CREATE TABLE `fin_receipt`  (
  `receipt_id` bigint(20) NOT NULL COMMENT '收付款单ID(雪花)',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `receipt_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收付款单号',
  `receipt_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收付款类型 CASH/BANK/ALIPAY/WECHAT/OTHER',
  `direction` char(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方向 AR=应收收款 AP=应付付款',
  `client_id` bigint(20) NULL DEFAULT NULL COMMENT '客户ID(direction=AR)',
  `vendor_id` bigint(20) NULL DEFAULT NULL COMMENT '供应商ID(direction=AP)',
  `payer_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '付款方名称',
  `amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '单据金额',
  `settled_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '已核销金额',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'CNY' COMMENT '币种',
  `exchange_rate` decimal(18, 6) NULL DEFAULT 1.000000 COMMENT '汇率',
  `third_party_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '第三方流水号',
  `pay_order_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '支付订单号(跨库关联 pay_order,不JOIN)',
  `source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'MANUAL' COMMENT '来源 MANUAL/PAY_CALLBACK',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '状态 DRAFT/CONFIRMED/SETTLED/CANCELLED',
  `receipt_date` date NULL DEFAULT NULL COMMENT '收付款日期(凭证日期)',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `version` int(11) NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  PRIMARY KEY (`receipt_id`) USING BTREE,
  UNIQUE INDEX `uk_receipt_no`(`receipt_no`, `tenant_id`) USING BTREE,
  UNIQUE INDEX `uk_pay_order`(`pay_order_number`, `tenant_id`) USING BTREE,
  INDEX `idx_client`(`client_id`) USING BTREE,
  INDEX `idx_vendor`(`vendor_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '收付款单(AR收款/AP付款合一)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fin_settlement
-- ----------------------------
DROP TABLE IF EXISTS `fin_settlement`;
CREATE TABLE `fin_settlement`  (
  `settlement_id` bigint(20) NOT NULL COMMENT '核销记录ID(雪花)',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `settlement_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '核销单号',
  `direction` char(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方向 AR/AP',
  `invoice_id` bigint(20) NOT NULL COMMENT '发票ID',
  `invoice_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发票号(冗余)',
  `invoice_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发票类型(冗余)',
  `receipt_id` bigint(20) NOT NULL COMMENT '收付款单ID',
  `settle_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '核销金额',
  `settle_date` date NULL DEFAULT NULL COMMENT '核销日期',
  `operator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作人',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  PRIMARY KEY (`settlement_id`) USING BTREE,
  UNIQUE INDEX `uk_settlement_no`(`settlement_no`, `tenant_id`) USING BTREE,
  INDEX `idx_invoice`(`invoice_id`) USING BTREE,
  INDEX `idx_receipt`(`receipt_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '应收应付核销记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for gl_account
-- ----------------------------
DROP TABLE IF EXISTS `gl_account`;
CREATE TABLE `gl_account`  (
  `account_id` bigint(20) NOT NULL COMMENT '科目ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `account_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目编码(如 1001)',
  `account_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目名称',
  `account_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目类型 ASSET-资产 LIABILITY-负债 EQUITY-权益 COST-成本 INCOME-收入 EXPENSE-费用',
  `balance_dir` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '余额方向 DEBIT-借 CREDIT-贷',
  `parent_id` bigint(20) NULL DEFAULT 0 COMMENT '父科目ID(0=顶级)',
  `level_num` int(11) NULL DEFAULT 1 COMMENT '层级(1=一级)',
  `path_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '路径ID串(如 6005001,6005002)',
  `path_names` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '路径名称串',
  `is_leaf` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '是否末级 0-否 1-是(仅末级可过账)',
  `is_recon` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否统驭科目 0-否 1-是(AR/AP/FA 子账汇总)',
  `recon_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '统驭类型 AR-应收 AP-应付 FA-固定资产',
  `is_open_item` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否未清项管理 0-否 1-是(行项目可清账)',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'CNY' COMMENT '币种(空=本位币)',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '状态 0-正常 1-停用',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序',
  `version` int(11) NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`account_id`) USING BTREE,
  UNIQUE INDEX `uk_account_code`(`account_code`, `tenant_id`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id`) USING BTREE,
  INDEX `idx_path_ids`(`path_ids`(64)) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '会计科目表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of gl_account
-- ----------------------------

-- ----------------------------
-- Table structure for gl_account_balance
-- ----------------------------
DROP TABLE IF EXISTS `gl_account_balance`;
CREATE TABLE `gl_account_balance`  (
  `balance_id` bigint(20) NOT NULL,
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000',
  `period_id` bigint(20) NOT NULL COMMENT '期间ID',
  `account_id` bigint(20) NOT NULL COMMENT '科目ID(末级)',
  `opening_debit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '期初借方',
  `opening_credit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '期初贷方',
  `period_debit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '本期借方发生',
  `period_credit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '本期贷方发生',
  `closing_debit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '期末借方',
  `closing_credit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '期末贷方',
  `year_opening_debit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '年初借方',
  `year_opening_credit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '年初贷方',
  `version` int(11) NULL DEFAULT 0 COMMENT '乐观锁',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  PRIMARY KEY (`balance_id`) USING BTREE,
  UNIQUE INDEX `uk_balance`(`period_id`, `account_id`, `tenant_id`) USING BTREE,
  INDEX `idx_account_id`(`account_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '科目余额表(试算/报表基座)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for gl_currency_rate
-- ----------------------------
DROP TABLE IF EXISTS `gl_currency_rate`;
CREATE TABLE `gl_currency_rate`  (
  `rate_id` bigint(20) NOT NULL,
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '币种(如 USD)',
  `base_currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'CNY' COMMENT '本位币',
  `rate_date` date NOT NULL COMMENT '汇率日期',
  `rate` decimal(18, 6) NOT NULL COMMENT '汇率(本币=原币×rate)',
  `rate_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'MIDDLE' COMMENT '类型 MIDDLE-中间价 BID-买入 ASK-卖出',
  `version` int(11) NULL DEFAULT 0,
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  PRIMARY KEY (`rate_id`) USING BTREE,
  UNIQUE INDEX `uk_rate`(`currency`, `rate_date`, `rate_type`, `tenant_id`) USING BTREE,
  INDEX `idx_rate_date`(`rate_date`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '币种汇率' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for gl_period
-- ----------------------------
DROP TABLE IF EXISTS `gl_period`;
CREATE TABLE `gl_period`  (
  `period_id` bigint(20) NOT NULL,
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000',
  `fiscal_year` int(11) NOT NULL COMMENT '会计年度',
  `period_no` int(11) NOT NULL COMMENT '期间号 1-12(0=调整期)',
  `period_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '名称(如 2026-07)',
  `start_date` date NOT NULL COMMENT '开始日期',
  `end_date` date NOT NULL COMMENT '结束日期',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'OPEN' COMMENT '状态 OPEN-开放 CLOSED-已关账 LOCKED-已锁定',
  `closing_step` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '月结进度(CLOSING_TRIAL/CLOSING_CARRY/CLOSING_REVAL/CLOSING_DONE,CLOSED 时冗余)',
  `closed_by` bigint(20) NULL DEFAULT NULL,
  `closed_time` datetime(0) NULL DEFAULT NULL,
  `closed_voucher_count` int(11) NULL DEFAULT 0 COMMENT '本期凭证数(结账时快照)',
  `closing_voucher_id` bigint(20) NULL DEFAULT NULL COMMENT '损益结转凭证ID(幂等回溯)',
  `revaluation_voucher_id` bigint(20) NULL DEFAULT NULL COMMENT '重估凭证ID(幂等回溯)',
  `version` int(11) NULL DEFAULT 0,
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  PRIMARY KEY (`period_id`) USING BTREE,
  UNIQUE INDEX `uk_period`(`fiscal_year`, `period_no`, `tenant_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '会计期间' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of gl_period
-- ----------------------------

-- ----------------------------
-- Table structure for gl_voucher
-- ----------------------------
DROP TABLE IF EXISTS `gl_voucher`;
CREATE TABLE `gl_voucher`  (
  `voucher_id` bigint(20) NOT NULL COMMENT '凭证ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000',
  `voucher_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '凭证号(业务号)',
  `voucher_word` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'J' COMMENT '凭证字 J-记 R-收 P-付 T-转',
  `voucher_date` date NOT NULL COMMENT '凭证日期(决定会计期间)',
  `period_id` bigint(20) NULL DEFAULT NULL COMMENT '会计期间ID(由 voucher_date 推导)',
  `voucher_source` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '来源 MANUAL-手工 SO_INVOICE-销售发票 PU_INVOICE-采购发票 RECEIPT-收付款 DEPRECIATION-折旧 COST-成本 ADJUSTMENT-调整',
  `source_id` bigint(20) NULL DEFAULT NULL COMMENT '来源单据ID',
  `source_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源单据号(冗余)',
  `attachment_count` int(11) NULL DEFAULT 0 COMMENT '附件张数',
  `total_debit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '借方合计',
  `total_credit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '贷方合计',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'CNY' COMMENT '本位币',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '状态 DRAFT-草稿 POSTED-已过账 CANCELLED-已作废',
  `posted_by` bigint(20) NULL DEFAULT NULL COMMENT '过账人',
  `posted_time` datetime(0) NULL DEFAULT NULL COMMENT '过账时间',
  `version` int(11) NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  PRIMARY KEY (`voucher_id`) USING BTREE,
  UNIQUE INDEX `uk_voucher_no`(`voucher_no`, `tenant_id`) USING BTREE,
  INDEX `idx_period_id`(`period_id`) USING BTREE,
  INDEX `idx_voucher_date`(`voucher_date`) USING BTREE,
  INDEX `idx_source`(`voucher_source`, `source_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '记账凭证头' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for gl_voucher_line
-- ----------------------------
DROP TABLE IF EXISTS `gl_voucher_line`;
CREATE TABLE `gl_voucher_line`  (
  `line_id` bigint(20) NOT NULL COMMENT '行ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000',
  `voucher_id` bigint(20) NOT NULL COMMENT '凭证ID',
  `line_no` int(11) NULL DEFAULT 0 COMMENT '行号',
  `account_id` bigint(20) NOT NULL COMMENT '科目ID(须末级)',
  `account_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '科目编码(冗余)',
  `account_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '科目名称(冗余)',
  `summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '摘要',
  `debit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '借方金额(本币)',
  `credit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '贷方金额(本币)',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'CNY' COMMENT '原币',
  `amount_currency` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '原币金额',
  `exchange_rate` decimal(18, 6) NULL DEFAULT 1.000000 COMMENT '汇率',
  `partner_id` bigint(20) NULL DEFAULT NULL COMMENT '往来对象ID(客户/供应商,统驭科目用)',
  `partner_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'CLIENT-客户 VENDOR-供应商',
  `open_item` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否未清项 0-否 1-是',
  `cleared` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否已清账 0-否 1-是',
  `cleared_by` bigint(20) NULL DEFAULT NULL COMMENT '清账核销记录ID(F1 fin_settlement.settlement_id)',
  `sort_order` int(11) NULL DEFAULT 0,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  PRIMARY KEY (`line_id`) USING BTREE,
  INDEX `idx_voucher_id`(`voucher_id`) USING BTREE,
  INDEX `idx_account_id`(`account_id`) USING BTREE,
  INDEX `idx_partner`(`partner_type`, `partner_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '记账凭证明细行' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for po_requisition
-- ----------------------------
DROP TABLE IF EXISTS `po_requisition`;
CREATE TABLE `po_requisition`  (
  `requisition_id` bigint(20) NOT NULL COMMENT '请购单ID',
  `requisition_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请购单号',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '状态',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '部门ID（关联sys_dept）',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部门名称',
  `applicant_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '申请人',
  `required_date` datetime(0) NULL DEFAULT NULL COMMENT '需求日期',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  `applicant_id` bigint(20) NULL DEFAULT NULL COMMENT '申请人ID（关联sys_user）',
  PRIMARY KEY (`requisition_id`) USING BTREE,
  UNIQUE INDEX `uk_po_requisition_no`(`requisition_no`, `tenant_id`) USING BTREE,
  INDEX `idx_po_requisition_status`(`status`) USING BTREE,
  INDEX `idx_po_requisition_applicant`(`applicant_name`) USING BTREE,
  INDEX `idx_po_requisition_dept`(`dept_id`) USING BTREE,
  INDEX `idx_po_requisition_applicant_id`(`applicant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '请购单主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for po_requisition_detail
-- ----------------------------
DROP TABLE IF EXISTS `po_requisition_detail`;
CREATE TABLE `po_requisition_detail`  (
  `detail_id` bigint(20) NOT NULL COMMENT '明细ID',
  `requisition_id` bigint(20) NOT NULL COMMENT '请购单ID',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料规格',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位',
  `required_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '需求数量',
  `issued_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '已发料数量',
  `stock_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '库存数量',
  `shortage_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '缺料数量',
  `required_date` datetime(0) NULL DEFAULT NULL COMMENT '需求日期',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'draft' COMMENT '状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源类型',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`detail_id`) USING BTREE,
  INDEX `idx_po_requisition_detail_req`(`requisition_id`) USING BTREE,
  INDEX `idx_po_requisition_detail_material`(`material_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '请购单明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for prd_capacity_calendar
-- ----------------------------
DROP TABLE IF EXISTS `prd_capacity_calendar`;
CREATE TABLE `prd_capacity_calendar`  (
  `calendar_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '日历ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `calendar_date` date NOT NULL COMMENT '日期',
  `object_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象类型: WORKSHOP-车间, WORKSTATION-工位, LINE-生产线',
  `object_id` bigint(20) NOT NULL COMMENT '对象ID',
  `object_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '对象编码',
  `object_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '对象名称',
  `shift_id` bigint(20) NULL DEFAULT NULL COMMENT '班次ID',
  `shift_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '班次编码',
  `shift_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '班次名称',
  `available_hours` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '可用工时(小时)',
  `planned_hours` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '已计划工时(小时)',
  `actual_hours` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '实际已用工时(小时)',
  `efficiency` decimal(5, 2) NULL DEFAULT 100.00 COMMENT '效率系数(%)',
  `effective_hours` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '有效产能',
  `remaining_hours` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '剩余产能',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE-有效, CLOSED-已关闭',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`calendar_id`) USING BTREE,
  UNIQUE INDEX `uk_date_object_shift`(`calendar_date`, `object_type`, `object_id`, `shift_id`, `tenant_id`) USING BTREE,
  INDEX `idx_date`(`calendar_date`) USING BTREE,
  INDEX `idx_object`(`object_type`, `object_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1048 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '产能日历表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_capacity_calendar
-- ----------------------------

-- ----------------------------
-- Table structure for prd_material_requirement
-- ----------------------------
DROP TABLE IF EXISTS `prd_material_requirement`;
CREATE TABLE `prd_material_requirement`  (
  `requirement_id` bigint(20) NOT NULL COMMENT '物料需求单ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `requirement_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '物料需求单编号',
  `plan_id` bigint(20) NULL DEFAULT NULL COMMENT '生产计划ID',
  `plan_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '生产计划编号',
  `bom_id` bigint(20) NULL DEFAULT NULL COMMENT 'BOM ID',
  `requirement_date` datetime(0) NULL DEFAULT NULL COMMENT '需求日期',
  `total_material_types` bigint(20) NULL DEFAULT 0 COMMENT '物料种类总数',
  `total_required_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '需求总量',
  `source_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源类型',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '状态',
  `planner_id` bigint(20) NULL DEFAULT NULL COMMENT '计划员ID',
  `planner_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计划员',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部门',
  `confirmed_time` datetime(0) NULL DEFAULT NULL COMMENT '确认时间',
  `issued_time` datetime(0) NULL DEFAULT NULL COMMENT '发料时间',
  `closed_time` datetime(0) NULL DEFAULT NULL COMMENT '关闭时间',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料规格',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `parent_requirement_id` bigint(20) NULL DEFAULT NULL COMMENT '父级物料需求单ID',
  PRIMARY KEY (`requirement_id`) USING BTREE,
  UNIQUE INDEX `uk_requirement_no`(`requirement_no`, `tenant_id`) USING BTREE,
  INDEX `idx_plan_id`(`plan_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '物料需求单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_material_requirement
-- ----------------------------

-- ----------------------------
-- Table structure for prd_material_requirement_detail
-- ----------------------------
DROP TABLE IF EXISTS `prd_material_requirement_detail`;
CREATE TABLE `prd_material_requirement_detail`  (
  `detail_id` bigint(20) NOT NULL COMMENT '需求明细ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `requirement_id` bigint(20) NOT NULL COMMENT '物料需求单ID',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料规格',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位',
  `source_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源类型',
  `bom_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT 'BOM标准用量',
  `loss_rate` decimal(18, 6) NULL DEFAULT 0.000000 COMMENT '损耗率(%)',
  `required_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '需求数量',
  `issued_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '已发料数量',
  `stock_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '当前库存数量',
  `shortage_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '缺料数量',
  `operation_step` bigint(20) NULL DEFAULT NULL COMMENT '工序步骤',
  `workstation_id` bigint(20) NULL DEFAULT NULL COMMENT '工作中心ID',
  `workstation_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作中心名称',
  `lead_time` bigint(20) NULL DEFAULT NULL COMMENT '提前期(小时)',
  `required_date` datetime(0) NULL DEFAULT NULL COMMENT '需求日期',
  `status` bigint(20) NULL DEFAULT NULL COMMENT '状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `backflush_flag` tinyint(4) NULL DEFAULT 0 COMMENT '是否倒冲物料: 0-否, 1-是',
  `actual_consumed_qty` decimal(14, 4) NULL DEFAULT 0.0000 COMMENT '实际消耗数量',
  PRIMARY KEY (`detail_id`) USING BTREE,
  INDEX `idx_requirement_id`(`requirement_id`) USING BTREE,
  INDEX `idx_material_id`(`material_id`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '物料需求单明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_material_requirement_detail
-- ----------------------------

-- ----------------------------
-- Table structure for prd_production_plan
-- ----------------------------
DROP TABLE IF EXISTS `prd_production_plan`;
CREATE TABLE `prd_production_plan`  (
  `plan_id` bigint(20) NOT NULL COMMENT '生产计划ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `plan_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生产计划编号',
  `plan_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计划名称',
  `version` bigint(20) NULL DEFAULT 1 COMMENT '版本号',
  `original_plan_id` bigint(20) NULL DEFAULT NULL COMMENT '原始计划ID',
  `reference_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '参考单据号',
  `plan_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计划类型',
  `plan_date` datetime(0) NULL DEFAULT NULL COMMENT '计划日期',
  `start_date` datetime(0) NULL DEFAULT NULL COMMENT '计划开始日期',
  `end_date` datetime(0) NULL DEFAULT NULL COMMENT '计划结束日期',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '状态',
  `priority` bigint(20) NULL DEFAULT NULL COMMENT '优先级',
  `planner_id` bigint(20) NULL DEFAULT NULL COMMENT '计划员ID',
  `planner_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计划员',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '生产部门ID',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '生产部门',
  `total_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '计划总数量',
  `confirmed_time` datetime(0) NULL DEFAULT NULL COMMENT '确认时间',
  `released_time` datetime(0) NULL DEFAULT NULL COMMENT '下达时间',
  `closed_time` datetime(0) NULL DEFAULT NULL COMMENT '关闭时间',
  `bom_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'bom名称',
  `bom_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'bom版本',
  `is_current` bigint(20) NULL DEFAULT 0 COMMENT '是否当前版本',
  `bom_id` bigint(20) NULL DEFAULT NULL COMMENT 'BOM ID',
  `attr4` bigint(20) NULL DEFAULT NULL COMMENT '预留字段4',
  `material_requirement_id` bigint(20) NULL DEFAULT NULL COMMENT '物料需求单ID',
  `material_requirement_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料需求单编号',
  `order_line_id` bigint(20) NULL DEFAULT NULL COMMENT '销售订单子表id',
  `order_line_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '销售订单子表行号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`plan_id`) USING BTREE,
  UNIQUE INDEX `uk_plan_no`(`plan_no`, `tenant_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_plan_date`(`plan_date`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '生产计划表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_production_plan
-- ----------------------------

-- ----------------------------
-- Table structure for prd_rework_order
-- ----------------------------
DROP TABLE IF EXISTS `prd_rework_order`;
CREATE TABLE `prd_rework_order`  (
  `rework_id` bigint(20) NOT NULL COMMENT '返工单ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `rework_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '返工单号',
  `source_wo_id` bigint(20) NULL DEFAULT NULL COMMENT '来源工单ID',
  `source_wo_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源工单编号',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规格型号',
  `base_uom_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位名称',
  `rework_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '返工数量',
  `rework_reason` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '返工原因',
  `actual_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '实际数量',
  `scrap_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '报废数量',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '返工状态',
  `del_flag` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`rework_id`) USING BTREE,
  UNIQUE INDEX `uk_rework_no`(`rework_no`, `tenant_id`) USING BTREE,
  INDEX `idx_rework_source_wo`(`source_wo_id`) USING BTREE,
  INDEX `idx_rework_material`(`material_id`) USING BTREE,
  INDEX `idx_rework_status`(`status`) USING BTREE,
  INDEX `idx_rework_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '返工订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for prd_schedule_capacity_booking
-- ----------------------------
DROP TABLE IF EXISTS `prd_schedule_capacity_booking`;
CREATE TABLE `prd_schedule_capacity_booking`  (
  `booking_id` bigint(20) NOT NULL COMMENT '雪花ID，产能预约记录',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `plan_id` bigint(20) NOT NULL COMMENT '排程方案ID',
  `task_id` bigint(20) NOT NULL COMMENT '排程工序任务ID',
  `calendar_id` bigint(20) NOT NULL COMMENT '产能日历ID',
  `load_date` date NOT NULL COMMENT '预约日期（日历日期快照）',
  `booked_hours` decimal(12, 2) NOT NULL COMMENT '预约工时',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`booking_id`) USING BTREE,
  UNIQUE INDEX `uk_pscb_tenant_plan_task_calendar`(`tenant_id`, `plan_id`, `task_id`, `calendar_id`) USING BTREE,
  INDEX `idx_pscb_tenant_plan`(`tenant_id`, `plan_id`) USING BTREE,
  INDEX `idx_pscb_tenant_calendar`(`tenant_id`, `calendar_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'APS产能日历预约溯源表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_schedule_capacity_booking
-- ----------------------------

-- ----------------------------
-- Table structure for prd_schedule_no_sequence
-- ----------------------------
DROP TABLE IF EXISTS `prd_schedule_no_sequence`;
CREATE TABLE `prd_schedule_no_sequence`  (
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `plan_date` date NOT NULL COMMENT '排程起始日（编号日期段）',
  `last_seq` int(11) NOT NULL DEFAULT 0 COMMENT '该租户该日起始日已保留的最大流水号',
  PRIMARY KEY (`tenant_id`, `plan_date`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'APS方案编号保留序列（含软删除）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_schedule_no_sequence
-- ----------------------------

-- ----------------------------
-- Table structure for prd_schedule_plan
-- ----------------------------
DROP TABLE IF EXISTS `prd_schedule_plan`;
CREATE TABLE `prd_schedule_plan`  (
  `plan_id` bigint(20) NOT NULL COMMENT '排程方案ID',
  `plan_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方案编号(APS+yyyyMMdd+4位流水)',
  `plan_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '方案名称',
  `workshop_id` bigint(20) NULL DEFAULT NULL COMMENT '车间ID(空=全部车间)',
  `workshop_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '车间名称',
  `start_date` date NOT NULL COMMENT '排产起始日',
  `horizon_days` int(11) NOT NULL DEFAULT 14 COMMENT '排产跨度(天)',
  `strategy` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EDD' COMMENT '排序策略: EDD-最早交期, CR-临界比, PRIORITY-优先级',
  `wo_count` int(11) NULL DEFAULT 0 COMMENT '参与排产工单数',
  `task_count` int(11) NULL DEFAULT 0 COMMENT '排产工序任务数',
  `skipped_count` int(11) NULL DEFAULT 0 COMMENT '跳过工单数(无工艺路线等)',
  `total_hours` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '总负荷工时(小时)',
  `delayed_count` int(11) NULL DEFAULT 0 COMMENT '拖期工单数',
  `makespan_date` date NULL DEFAULT NULL COMMENT '总完工日期',
  `utilization_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '资源利用率快照JSON[{resourceName,bookedHours,availableHours,rate}]',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'COMPLETED' COMMENT '状态: COMPLETED-已生成, PUBLISHED-已发布',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `decision_run_id` bigint(20) NULL DEFAULT NULL COMMENT 'AI决策运行ID',
  `decision_action_id` bigint(20) NULL DEFAULT NULL COMMENT 'AI决策动作ID',
  `decision_idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租户内AI决策幂等键',
  `decision_scenario_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'AI决策场景编码',
  `decision_work_order_ids_json` varchar(4000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '显式工单ID十进制字符串JSON',
  `version` int(11) NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `capacity_calc_version` tinyint(4) NOT NULL DEFAULT 0 COMMENT '产能计算版本: 0-旧口径, 2-按日产能预约',
  PRIMARY KEY (`plan_id`) USING BTREE,
  UNIQUE INDEX `uk_psp_tenant_plan_no`(`tenant_id`, `plan_no`) USING BTREE,
  UNIQUE INDEX `uk_psp_decision_idem`(`tenant_id`, `decision_idempotency_key`) USING BTREE,
  INDEX `idx_psp_tenant`(`tenant_id`) USING BTREE,
  INDEX `idx_psp_no`(`plan_no`) USING BTREE,
  INDEX `idx_psp_decision_run`(`tenant_id`, `decision_run_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'APS排程方案表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_schedule_plan
-- ----------------------------

-- ----------------------------
-- Table structure for prd_schedule_task
-- ----------------------------
DROP TABLE IF EXISTS `prd_schedule_task`;
CREATE TABLE `prd_schedule_task`  (
  `task_id` bigint(20) NOT NULL COMMENT '任务ID',
  `plan_id` bigint(20) NOT NULL COMMENT '排程方案ID',
  `wo_id` bigint(20) NOT NULL COMMENT '生产工单ID',
  `wo_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工单编号',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '产品编码',
  `material_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '产品名称',
  `seq_num` int(11) NULL DEFAULT NULL COMMENT '工序序号(工艺路线步骤序号)',
  `step_id` bigint(20) NULL DEFAULT NULL COMMENT '工艺路线步骤ID',
  `process_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工序编码',
  `process_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工序名称',
  `resource_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资源类型: WORKSTATION-工作站, WORKSHOP-车间, OUTSOURCE-委外',
  `resource_id` bigint(20) NULL DEFAULT NULL COMMENT '资源ID(工作站/车间)',
  `resource_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资源名称',
  `setup_hours` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '准备工时(小时)',
  `process_hours` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '加工工时(小时)=标准工时×剩余数量',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT '开始时间(起始日00:00)',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '结束时间(末日23:59:59)',
  `duration_days` int(11) NULL DEFAULT 1 COMMENT '占用天数',
  `delay_flag` tinyint(4) NULL DEFAULT 0 COMMENT '拖期标记(所属工单拖期时置1)',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`task_id`) USING BTREE,
  INDEX `idx_pst_plan`(`plan_id`) USING BTREE,
  INDEX `idx_pst_wo`(`wo_id`) USING BTREE,
  INDEX `idx_pst_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'APS排程工序任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_schedule_task
-- ----------------------------

-- ----------------------------
-- Table structure for prd_schedule_task_day_load
-- ----------------------------
DROP TABLE IF EXISTS `prd_schedule_task_day_load`;
CREATE TABLE `prd_schedule_task_day_load`  (
  `load_id` bigint(20) NOT NULL COMMENT '雪花ID，工序按日负荷记录',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `plan_id` bigint(20) NOT NULL COMMENT '排程方案ID',
  `task_id` bigint(20) NOT NULL COMMENT '排程工序任务ID',
  `resource_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源类型: WORKSTATION/WORKSHOP/OUTSOURCE',
  `resource_id` bigint(20) NOT NULL COMMENT '资源ID',
  `load_date` date NOT NULL COMMENT '负荷日期',
  `planned_hours` decimal(12, 2) NOT NULL COMMENT '当日计划占用工时',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`load_id`) USING BTREE,
  UNIQUE INDEX `uk_psdl_tenant_plan_task_date`(`tenant_id`, `plan_id`, `task_id`, `load_date`) USING BTREE,
  INDEX `idx_psdl_tenant_plan`(`tenant_id`, `plan_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'APS工序按日负荷溯源表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_schedule_task_day_load
-- ----------------------------

-- ----------------------------
-- Table structure for prd_subcontract
-- ----------------------------
DROP TABLE IF EXISTS `prd_subcontract`;
CREATE TABLE `prd_subcontract`  (
  `subcontract_id` bigint(20) NOT NULL COMMENT '委外单ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `subcontract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '委外单号',
  `vendor_id` bigint(20) NULL DEFAULT NULL COMMENT '供应商ID',
  `vendor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规格型号',
  `base_uom_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位名称',
  `planned_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '计划数量',
  `actual_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '实际数量',
  `unit_price` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '单价',
  `total_amount` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '总金额',
  `plan_start_date` date NULL DEFAULT NULL COMMENT '计划开始日期',
  `plan_end_date` date NULL DEFAULT NULL COMMENT '计划结束日期',
  `actual_start_date` date NULL DEFAULT NULL COMMENT '实际开始日期',
  `actual_end_date` date NULL DEFAULT NULL COMMENT '实际结束日期',
  `wo_id` bigint(20) NULL DEFAULT NULL COMMENT '关联工单ID',
  `wo_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联工单编号',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '委外状态',
  `del_flag` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `bom_id` bigint(20) NULL DEFAULT NULL COMMENT '关联BOM ID(快照来源)',
  `routing_id` bigint(20) NULL DEFAULT NULL COMMENT '工艺路线ID',
  `process_requirement` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '工艺要求(质量标准/特殊工艺/AOI/FCT等)',
  `sn_generated_qty` int(11) NULL DEFAULT 0 COMMENT 'SN已生成数量',
  `target_warehouse_id` bigint(20) NULL DEFAULT NULL COMMENT '收货目标仓库ID(默认半成品仓)',
  `target_warehouse_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收货目标仓库名称',
  PRIMARY KEY (`subcontract_id`) USING BTREE,
  UNIQUE INDEX `uk_subcontract_no`(`subcontract_no`, `tenant_id`) USING BTREE,
  INDEX `idx_subcontract_vendor`(`vendor_id`) USING BTREE,
  INDEX `idx_subcontract_material`(`material_id`) USING BTREE,
  INDEX `idx_subcontract_status`(`status`) USING BTREE,
  INDEX `idx_subcontract_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '委外订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for prd_subcontract_bom_line
-- ----------------------------
DROP TABLE IF EXISTS `prd_subcontract_bom_line`;
CREATE TABLE `prd_subcontract_bom_line`  (
  `line_id` bigint(20) NOT NULL COMMENT '快照行ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `subcontract_id` bigint(20) NOT NULL COMMENT '委外订单ID',
  `bom_detail_id` bigint(20) NULL DEFAULT NULL COMMENT '来源BOM行ID(bd_bom_detail)',
  `material_id` bigint(20) NOT NULL COMMENT '子件物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规格型号',
  `base_uom_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位名称',
  `quantity_per` decimal(18, 6) NULL DEFAULT 0.000000 COMMENT '单耗(每母件)',
  `loss_rate` decimal(9, 4) NULL DEFAULT 0.0000 COMMENT '损耗率(%)',
  `demand_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '需求量=计划数×单耗×(1+损耗)',
  `issued_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '已发料量',
  `supply_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'SELF_PROVIDED' COMMENT '供应方: SELF_PROVIDED自备/VENDOR_PROVIDED外协厂供/CUSTOMER_PROVIDED客供',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`line_id`) USING BTREE,
  INDEX `idx_sc_bom_line_sc`(`tenant_id`, `subcontract_id`) USING BTREE,
  INDEX `idx_sc_bom_line_material`(`material_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '委外订单BOM快照行' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for prd_subcontract_quote
-- ----------------------------
DROP TABLE IF EXISTS `prd_subcontract_quote`;
CREATE TABLE `prd_subcontract_quote`  (
  `quote_id` bigint(20) NOT NULL COMMENT '报价ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `subcontract_id` bigint(20) NOT NULL COMMENT '委外订单ID',
  `vendor_id` bigint(20) NULL DEFAULT NULL COMMENT '供应商ID',
  `vendor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `unit_price` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '加工单价',
  `currency` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'CNY' COMMENT '币种',
  `lead_time_days` int(11) NULL DEFAULT NULL COMMENT '交期(天)',
  `tooling_fee` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '治具/钢网费',
  `quote_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'PENDING' COMMENT '状态: PENDING待确认/SELECTED已选定/NOT_SELECTED未选中/EXPIRED已失效',
  `valid_until` date NULL DEFAULT NULL COMMENT '报价有效期',
  `quote_time` datetime(0) NULL DEFAULT NULL COMMENT '报价时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`quote_id`) USING BTREE,
  INDEX `idx_sc_quote_sc`(`tenant_id`, `subcontract_id`) USING BTREE,
  INDEX `idx_sc_quote_vendor`(`vendor_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '委外订单报价记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for prd_work_order
-- ----------------------------
DROP TABLE IF EXISTS `prd_work_order`;
CREATE TABLE `prd_work_order`  (
  `wo_id` bigint(20) NOT NULL COMMENT '工单ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `wo_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工单编号',
  `plan_id` bigint(20) NULL DEFAULT NULL COMMENT '来源计划ID',
  `plan_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计划名称',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源类型',
  `source_id` bigint(20) NULL DEFAULT NULL COMMENT '来源单据ID',
  `source_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '销售订单编号',
  `source_line_id` bigint(20) NULL DEFAULT NULL COMMENT '来源单据行ID',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '产品物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '产品编码',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '产品名称',
  `material_spec` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '产品规格',
  `planned_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '计划数量',
  `completed_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '已完成数量',
  `scrap_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '报废数量',
  `unit_id` bigint(20) NULL DEFAULT NULL COMMENT '单位id',
  `unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位名称',
  `plan_start_date` datetime(0) NULL DEFAULT NULL COMMENT '计划开始日期',
  `plan_end_date` datetime(0) NULL DEFAULT NULL COMMENT '计划结束日期',
  `actual_start_date` datetime(0) NULL DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_date` datetime(0) NULL DEFAULT NULL COMMENT '实际结束时间',
  `wo_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工单状态',
  `workshop_id` bigint(20) NULL DEFAULT NULL COMMENT '车间ID',
  `workshop_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '车间名称',
  `workstation_id` bigint(20) NULL DEFAULT NULL COMMENT '工作站ID',
  `workstation_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作站名称',
  `production_line_id` bigint(20) NULL DEFAULT NULL COMMENT '生产线ID',
  `responsible_id` bigint(20) NULL DEFAULT NULL COMMENT '负责人ID',
  `responsible_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '负责人',
  `team_id` bigint(20) NULL DEFAULT NULL COMMENT '班组ID',
  `team_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '班组',
  `priority` bigint(20) NULL DEFAULT NULL COMMENT '优先级',
  `bom_id` bigint(20) NULL DEFAULT NULL COMMENT 'BOMid',
  `bom_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'BOM版本',
  `bom_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'BOM名称',
  `attr2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `attr3` bigint(20) NULL DEFAULT NULL COMMENT '预留字段3',
  `attr4` bigint(20) NULL DEFAULT NULL COMMENT '预留字段4',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `select_flow_id` bigint(20) NULL DEFAULT NULL COMMENT '已选审批流程模板ID',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `wo_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'NORMAL' COMMENT '工单类型:NORMAL-正常,SUBCONTRACT-委外,REWORK-返工',
  `backflush_flag` tinyint(4) NULL DEFAULT 0 COMMENT '是否倒冲工单: 0-否, 1-是',
  `issued_qty` decimal(14, 4) NULL DEFAULT 0.0000 COMMENT '累计发料数量',
  `quality_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '质检状态(PENDING/QUALIFIED/UNQUALIFIED/PARTIAL) - IPQC聚合',
  `quality_check_id` bigint(20) NULL DEFAULT NULL COMMENT '质检记录ID(IPQC)',
  `quality_check_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '质检单号(IPQC)',
  `inspector_id` bigint(20) NULL DEFAULT NULL COMMENT '检验员ID',
  `inspector_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '检验员姓名',
  `inspect_time` datetime(0) NULL DEFAULT NULL COMMENT '检验时间',
  `client_id` bigint(20) NULL DEFAULT NULL COMMENT '客户ID(bd_client, 来源销售订单头)',
  `client_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '客户名称(冗余)',
  `customer_product_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '客户产品代号(来源销售订单行)',
  PRIMARY KEY (`wo_id`) USING BTREE,
  UNIQUE INDEX `uk_wo_no`(`wo_no`, `tenant_id`) USING BTREE,
  INDEX `idx_plan_id`(`plan_id`) USING BTREE,
  INDEX `idx_material_id`(`material_id`) USING BTREE,
  INDEX `idx_wo_status`(`wo_status`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '生产工单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_work_order
-- ----------------------------

-- ----------------------------
-- Table structure for prd_work_order_resource
-- ----------------------------
DROP TABLE IF EXISTS `prd_work_order_resource`;
CREATE TABLE `prd_work_order_resource`  (
  `id` bigint(20) NOT NULL COMMENT '资源分配ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `wo_id` bigint(20) NOT NULL COMMENT '工单ID',
  `resource_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源类型：WORKSHOP-车间, WORKSTATION-工作站, EQUIPMENT-设备, TEAM-班组, PRODUCTION_LINE-生产线',
  `resource_id` bigint(20) NULL DEFAULT NULL COMMENT '资源ID',
  `resource_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资源编码',
  `resource_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资源名称',
  `seq` int(11) NULL DEFAULT 0 COMMENT '资源顺序/工序顺序',
  `parent_id` bigint(20) NULL DEFAULT NULL COMMENT '父资源ID（如工作站所属车间ID）',
  `parent_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '父资源类型',
  `plan_start_time` datetime(0) NULL DEFAULT NULL COMMENT '计划开始时间',
  `plan_end_time` datetime(0) NULL DEFAULT NULL COMMENT '计划结束时间',
  `actual_start_time` datetime(0) NULL DEFAULT NULL COMMENT '实际开始时间',
  `actual_end_time` datetime(0) NULL DEFAULT NULL COMMENT '实际结束时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'PENDING' COMMENT '状态：PENDING-待执行, PROCESSING-执行中, COMPLETED-已完成',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_wo_id`(`wo_id`) USING BTREE,
  INDEX `idx_resource_type`(`resource_type`) USING BTREE,
  INDEX `idx_resource_id`(`resource_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '生产工单资源分配表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prd_work_order_resource
-- ----------------------------

-- ----------------------------
-- Table structure for prd_work_report
-- ----------------------------
DROP TABLE IF EXISTS `prd_work_report`;
CREATE TABLE `prd_work_report`  (
  `report_id` bigint(20) NOT NULL COMMENT '报工记录ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `report_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '报工单编号',
  `report_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '报工类型：NORMAL-正常报工，REWORK-返工，REPAIR-返修，OVERTIME-加班',
  `report_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '报工状态：DRAFT-草稿，SUBMITTED-已提交，APPROVED-已审核，REJECTED-已驳回',
  `wo_id` bigint(20) NULL DEFAULT NULL COMMENT '工单ID',
  `wo_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工单编号',
  `wo_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工单名称',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '产品物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '产品物料编码',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '产品物料名称',
  `specification` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规格型号',
  `unit_id` bigint(20) NULL DEFAULT NULL COMMENT '单位ID',
  `unit_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位编码',
  `unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位名称',
  `route_id` bigint(20) NULL DEFAULT NULL COMMENT '工艺流程ID',
  `route_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工艺流程编号',
  `route_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工艺流程名称',
  `process_id` bigint(20) NULL DEFAULT NULL COMMENT '工序ID',
  `process_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工序编码',
  `process_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工序名称',
  `operation_step` bigint(20) NULL DEFAULT NULL COMMENT '工序步骤序号',
  `operation_seq` bigint(20) NULL DEFAULT NULL COMMENT '当前工序报工次数（用于多次报工）',
  `task_id` bigint(20) NULL DEFAULT NULL COMMENT '生产任务ID',
  `task_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '生产任务编号',
  `workstation_id` bigint(20) NULL DEFAULT NULL COMMENT '工作站ID',
  `workstation_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作站编码',
  `workstation_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作站名称',
  `workshop_id` bigint(20) NULL DEFAULT NULL COMMENT '车间ID',
  `workshop_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '车间名称',
  `equipment_id` bigint(20) NULL DEFAULT NULL COMMENT '设备ID',
  `equipment_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备编码',
  `equipment_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备名称',
  `lot_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '生产批号/批次号',
  `batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '批次编号',
  `expire_date` datetime(0) NULL DEFAULT NULL COMMENT '过期日期/有效期至',
  `shift_id` bigint(20) NULL DEFAULT NULL COMMENT '班次ID',
  `shift_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '班次名称',
  `planned_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '计划数量（工序计划数量）',
  `reported_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '本次报工数量',
  `good_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '合格数量',
  `scrap_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '报废数量',
  `defect_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '不良品数量',
  `labor_scrap_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '工废数量（人为原因报废）',
  `material_scrap_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '料废数量（材料原因报废）',
  `other_scrap_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '其他原因报废数量',
  `uncheck_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '待检测数量',
  `cumulative_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '累计报工数量（到本次为止）',
  `remaining_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '剩余数量',
  `report_date` datetime(0) NULL DEFAULT NULL COMMENT '报工日期',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '结束时间',
  `labor_hours` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '人工工时（小时）',
  `machine_hours` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '机器工时（小时）',
  `setup_hours` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '准备工时（小时）',
  `wait_hours` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '等待工时（小时）',
  `pause_hours` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '暂停工时（小时）',
  `worker_id` bigint(20) NULL DEFAULT NULL COMMENT '操作工ID（主操作工）',
  `worker_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作工编码',
  `worker_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作工姓名',
  `team_id` bigint(20) NULL DEFAULT NULL COMMENT '班组ID',
  `team_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '班组编码',
  `team_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '班组名称',
  `helper_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '辅助人员ID列表（逗号分隔）',
  `helper_names` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '辅助人员姓名列表',
  `quality_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '质量状态：PENDING-待检，QUALIFIED-合格，UNQUALIFIED-不合格，PARTIAL-部分合格',
  `quality_check_id` bigint(20) NULL DEFAULT NULL COMMENT '质检记录ID',
  `quality_check_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '质检单号',
  `inspector_id` bigint(20) NULL DEFAULT NULL COMMENT '检验员ID',
  `inspector_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '检验员姓名',
  `inspect_time` datetime(0) NULL DEFAULT NULL COMMENT '检验时间',
  `report_channel` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '报工途径：PC-电脑端，APP-移动端，PDA-手持设备，AUTO-自动采集',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源类型：MANUAL-手工录入，SCAN-扫码，IMPORT-导入，INTERFACE-接口同步',
  `source_id` bigint(20) NULL DEFAULT NULL COMMENT '来源单据ID',
  `source_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源单据编号',
  `barcode` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '条码信息',
  `submit_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '提交人',
  `submit_time` datetime(0) NULL DEFAULT NULL COMMENT '提交时间',
  `audit_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime(0) NULL DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核意见',
  `attr1` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `attr3` bigint(20) NULL DEFAULT NULL COMMENT '预留字段3',
  `attr4` bigint(20) NULL DEFAULT NULL COMMENT '预留字段4',
  `deleted` tinyint(4) NULL DEFAULT 0 COMMENT '删除标志（0-未删除，1-已删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `batch_id` bigint(20) NULL DEFAULT NULL COMMENT '批次ID（关联 wm_batch，统一批次管理）',
  `batch_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '批次号（关联 wm_batch.batch_code，统一批次管理）',
  PRIMARY KEY (`report_id`) USING BTREE,
  UNIQUE INDEX `uk_report_no`(`report_no`, `tenant_id`) USING BTREE,
  INDEX `idx_wo_id`(`wo_id`) USING BTREE,
  INDEX `idx_material_id`(`material_id`) USING BTREE,
  INDEX `idx_report_status`(`report_status`) USING BTREE,
  INDEX `idx_quality_status`(`quality_status`) USING BTREE,
  INDEX `idx_report_date`(`report_date`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE,
  INDEX `idx_prd_work_report_batch_id`(`batch_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '生产报工表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for pu_certified_purchase_command
-- ----------------------------
DROP TABLE IF EXISTS `pu_certified_purchase_command`;
CREATE TABLE `pu_certified_purchase_command`  (
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `request_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '原始请求永久占用，不能删键重建',
  `request_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '身份及排序来源请求摘要',
  `actor_id` bigint(20) NOT NULL,
  `entry_type` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `material_id` bigint(20) NOT NULL,
  `vendor_id` bigint(20) NOT NULL,
  `window_end` date NOT NULL,
  `requisition_id` bigint(20) NOT NULL,
  `requisition_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_fingerprint` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `result_fingerprint` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '逐来源已提交申请行不可变摘要',
  `catalog_fingerprint` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '批准及转单前核对完整冻结目录，不含读取时钟',
  `command_status` varchar(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'COMMITTED',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  PRIMARY KEY (`tenant_id`, `request_key`) USING BTREE,
  UNIQUE INDEX `uk_certified_purchase_requisition`(`tenant_id`, `requisition_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '可信采购永久命令与ERP提交恢复凭据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pu_certified_purchase_command
-- ----------------------------

-- ----------------------------
-- Table structure for pu_certified_purchase_order_operation
-- ----------------------------
DROP TABLE IF EXISTS `pu_certified_purchase_order_operation`;
CREATE TABLE `pu_certified_purchase_order_operation`  (
  `command_id` bigint(20) NOT NULL,
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `order_id` bigint(20) NOT NULL,
  `request_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `request_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `actor_id` bigint(20) NOT NULL,
  `operation` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `expected_version` int(11) NOT NULL,
  `result_version` int(11) NOT NULL,
  `result_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `quote_id` bigint(20) NULL DEFAULT NULL,
  `quote_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL,
  `expected_arrival_date` date NULL DEFAULT NULL,
  `total_amount` decimal(18, 2) NULL DEFAULT NULL,
  `amount_excluding_tax` decimal(18, 2) NULL DEFAULT NULL,
  `tax_amount` decimal(18, 2) NULL DEFAULT NULL,
  `result_fingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `occurred_at` datetime(3) NULL,
  PRIMARY KEY (`command_id`) USING BTREE,
  UNIQUE INDEX `uk_operation_request`(`tenant_id`, `request_key`) USING BTREE,
  UNIQUE INDEX `uk_order_operation`(`tenant_id`, `order_id`, `operation`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'ERP提交结果永久重放；不依赖AI回写成功' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pu_certified_purchase_order_operation
-- ----------------------------

-- ----------------------------
-- Table structure for pu_certified_purchase_order_terms
-- ----------------------------
DROP TABLE IF EXISTS `pu_certified_purchase_order_terms`;
CREATE TABLE `pu_certified_purchase_order_terms`  (
  `quote_id` bigint(20) NOT NULL,
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `order_id` bigint(20) NOT NULL,
  `quote_version` int(11) NOT NULL,
  `request_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `request_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `entered_by` bigint(20) NOT NULL,
  `entered_at` datetime(3) NULL,
  `vendor_id` bigint(20) NOT NULL,
  `material_id` bigint(20) NOT NULL,
  `base_uom_id` bigint(20) NOT NULL,
  `source_request_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_fingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `catalog_fingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `order_fingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `quantity` decimal(18, 4) NOT NULL,
  `unit_price_excluding_tax` decimal(18, 4) NOT NULL,
  `tax_rate` decimal(10, 4) NOT NULL,
  `currency` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `exchange_rate` decimal(18, 6) NOT NULL,
  `promised_arrival_date` date NOT NULL,
  `valid_from` date NOT NULL,
  `valid_until` date NOT NULL,
  `supplier_quote_reference` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `supplier_contact` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `evidence_reference` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `evidence_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `payment_terms` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `delivery_terms` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `rounding_policy` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `quote_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  PRIMARY KEY (`quote_id`) USING BTREE,
  UNIQUE INDEX `uk_quote_request`(`tenant_id`, `request_key`) USING BTREE,
  UNIQUE INDEX `uk_order_quote_version`(`tenant_id`, `order_id`, `quote_version`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购供应确认条款不可变版本；无UPDATE/DELETE API' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pu_certified_purchase_order_terms
-- ----------------------------

-- ----------------------------
-- Table structure for pu_certified_purchase_order_terms_confirmation
-- ----------------------------
DROP TABLE IF EXISTS `pu_certified_purchase_order_terms_confirmation`;
CREATE TABLE `pu_certified_purchase_order_terms_confirmation`  (
  `confirmation_id` bigint(20) NOT NULL,
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `quote_id` bigint(20) NOT NULL,
  `quote_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `request_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `request_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `actor_id` bigint(20) NOT NULL,
  `permission_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `confirmed_at` datetime(3) NULL,
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`confirmation_id`) USING BTREE,
  UNIQUE INDEX `uk_confirmation_request`(`tenant_id`, `request_key`) USING BTREE,
  UNIQUE INDEX `uk_quote_confirmation`(`tenant_id`, `quote_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '不同操作人独立确认审计；只追加不替换' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pu_certified_purchase_order_terms_confirmation
-- ----------------------------

-- ----------------------------
-- Table structure for pu_contract
-- ----------------------------
DROP TABLE IF EXISTS `pu_contract`;
CREATE TABLE `pu_contract`  (
  `contract_id` bigint(20) NOT NULL COMMENT '合同ID',
  `contract_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同编号',
  `contract_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同名称',
  `vendor_id` bigint(20) NULL DEFAULT NULL COMMENT '供应商ID',
  `vendor_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `contract_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同类型 FRAMEWORK-框架合同 SPOT-现货合同 SERVICE-服务合同',
  `sign_date` datetime(0) NULL DEFAULT NULL COMMENT '签订日期',
  `effective_date` datetime(0) NULL DEFAULT NULL COMMENT '生效日期',
  `expiry_date` datetime(0) NULL DEFAULT NULL COMMENT '失效日期',
  `total_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '合同总金额',
  `tax_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '税额',
  `amount_excluding_tax` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '不含税总金额',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'CNY' COMMENT '币种',
  `payment_terms` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '付款条款',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '合同状态 DRAFT-草稿 APPROVING-审批中 APPROVED-已批准 EXECUTING-执行中 COMPLETED-已完成 TERMINATED-已终止 REJECTED-已驳回',
  `select_flow_id` bigint(20) NULL DEFAULT NULL COMMENT '审批流程ID',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `attr1` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `attr2` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `attr3` bigint(20) NULL DEFAULT NULL COMMENT '扩展字段3',
  `attr4` bigint(20) NULL DEFAULT NULL COMMENT '扩展字段4',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志(0代表存在 2代表删除)',
  PRIMARY KEY (`contract_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '采购合同头表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pu_contract
-- ----------------------------

-- ----------------------------
-- Table structure for pu_contract_line
-- ----------------------------
DROP TABLE IF EXISTS `pu_contract_line`;
CREATE TABLE `pu_contract_line`  (
  `line_id` bigint(20) NOT NULL COMMENT '行ID',
  `contract_id` bigint(20) NOT NULL COMMENT '合同ID',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料规格',
  `unit` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计量单位',
  `unit_price` decimal(18, 4) NULL DEFAULT NULL COMMENT '单价',
  `tax_rate` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '税率',
  `quantity` decimal(18, 4) NULL DEFAULT NULL COMMENT '数量',
  `line_amount` decimal(18, 4) NULL DEFAULT NULL COMMENT '行金额',
  `tax_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '行税额',
  `line_amount_excluding_tax` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '不含税行金额',
  `delivery_date` datetime(0) NULL DEFAULT NULL COMMENT '交货日期',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '排序号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `attr1` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '扩展字段1',
  `attr2` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '扩展字段2',
  `attr3` bigint(20) NULL DEFAULT NULL COMMENT '扩展字段3',
  `attr4` bigint(20) NULL DEFAULT NULL COMMENT '扩展字段4',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志(0代表存在 2代表删除)',
  PRIMARY KEY (`line_id`) USING BTREE,
  INDEX `idx_contract_id`(`contract_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '采购合同行表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pu_contract_line
-- ----------------------------

-- ----------------------------
-- Table structure for pu_invoice
-- ----------------------------
DROP TABLE IF EXISTS `pu_invoice`;
CREATE TABLE `pu_invoice`  (
  `invoice_id` bigint(20) NOT NULL COMMENT '发票ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `invoice_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发票号',
  `invoice_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发票代码',
  `invoice_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'VAT_SPECIAL' COMMENT '发票类型 VAT_SPECIAL-增值税专用 VAT_NORMAL-增值税普通 OTHER-其他',
  `vendor_id` bigint(20) NULL DEFAULT NULL COMMENT '供应商ID',
  `vendor_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `seller_tax_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '销售方纳税人识别号(供应商)',
  `seller_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '销售方发票抬头',
  `seller_bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '销售方开户行',
  `seller_bank_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '销售方银行账号',
  `seller_address_phone` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '销售方地址、电话',
  `po_id` bigint(20) NULL DEFAULT NULL COMMENT '采购订单ID',
  `contract_id` bigint(20) NULL DEFAULT NULL COMMENT '采购合同ID',
  `original_invoice_id` bigint(20) NULL DEFAULT NULL COMMENT '红冲原发票ID(NULL=蓝字正数)',
  `red_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否红字发票 0-否 1-是',
  `invoice_date` date NULL DEFAULT NULL COMMENT '开票日期',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'CNY' COMMENT '币种',
  `exchange_rate` decimal(10, 4) NULL DEFAULT 1.0000 COMMENT '汇率',
  `amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '金额(不含税)',
  `tax_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '税额',
  `total_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '价税合计',
  `verified_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '已核销(已付款)金额',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '发票状态 DRAFT-草稿 ISSUED-已收 VERIFIED-已核销 CANCELLED-已作废',
  `cert_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'UNCERTIFIED' COMMENT '认证状态 UNCERTIFIED-未认证 CERTIFIED-已认证 DEDUCTED-已抵扣 TRANSFERRED-已转出',
  `cert_date` date NULL DEFAULT NULL COMMENT '认证日期',
  `deductible_tax_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '可抵扣税额',
  `issue_channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'MANUAL' COMMENT '来源渠道 MANUAL-手工录入 ELECTRONIC-电子发票平台同步',
  `e_invoice_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '数电票号码',
  `pdf_oss_id` bigint(20) NULL DEFAULT NULL COMMENT '发票PDF的OSS对象ID(私有桶存ossId)',
  `ofd_oss_id` bigint(20) NULL DEFAULT NULL COMMENT '发票OFD的OSS对象ID',
  `version` int(11) NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `attr1` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr3` bigint(20) NULL DEFAULT NULL,
  `attr4` bigint(20) NULL DEFAULT NULL,
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`invoice_id`) USING BTREE,
  UNIQUE INDEX `uk_invoice_no`(`invoice_no`, `tenant_id`) USING BTREE,
  INDEX `idx_vendor_id`(`vendor_id`) USING BTREE,
  INDEX `idx_po_id`(`po_id`) USING BTREE,
  INDEX `idx_original_invoice_id`(`original_invoice_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_cert_status`(`cert_status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '采购进项发票表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for pu_invoice_line
-- ----------------------------
DROP TABLE IF EXISTS `pu_invoice_line`;
CREATE TABLE `pu_invoice_line`  (
  `line_id` bigint(20) NOT NULL COMMENT '发票行ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `invoice_id` bigint(20) NOT NULL COMMENT '发票ID',
  `line_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '行号',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `material_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `material_spec` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '数量',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位',
  `unit_price` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '单价(不含税)',
  `line_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '行金额(不含税)',
  `tax_rate` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '税率',
  `tax_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '税额',
  `total_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '价税合计',
  `po_line_id` bigint(20) NULL DEFAULT NULL COMMENT '采购订单行ID',
  `gr_line_id` bigint(20) NULL DEFAULT NULL COMMENT '收货单行ID(三单匹配用, wm_material_receive_line.line_id)',
  `contract_line_id` bigint(20) NULL DEFAULT NULL COMMENT '采购合同行ID',
  `sort_order` int(11) NULL DEFAULT 0,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr1` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr3` bigint(20) NULL DEFAULT NULL,
  `attr4` bigint(20) NULL DEFAULT NULL,
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  PRIMARY KEY (`line_id`) USING BTREE,
  INDEX `idx_invoice_id`(`invoice_id`) USING BTREE,
  INDEX `idx_material_id`(`material_id`) USING BTREE,
  INDEX `idx_po_line_id`(`po_line_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '采购进项发票明细行表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for pu_purchase_order
-- ----------------------------
DROP TABLE IF EXISTS `pu_purchase_order`;
CREATE TABLE `pu_purchase_order`  (
  `order_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '采购订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '采购订单号',
  `requisition_id` bigint(20) NULL DEFAULT NULL COMMENT '来源申请ID',
  `requisition_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源申请单号',
  `vendor_id` bigint(20) NULL DEFAULT NULL COMMENT '供应商ID',
  `vendor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `order_date` datetime(0) NULL DEFAULT NULL COMMENT '订单日期',
  `expected_arrival_date` datetime(0) NULL DEFAULT NULL COMMENT '预计到货日期',
  `currency` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'CNY' COMMENT '币别',
  `exchange_rate` decimal(18, 6) NULL DEFAULT 1.000000 COMMENT '汇率',
  `total_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '含税总金额',
  `amount_excluding_tax` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '不含税总金额',
  `tax_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '税额',
  `discount_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '折扣金额',
  `freight_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '运费金额',
  `discount_rate` decimal(10, 2) NULL DEFAULT NULL COMMENT '折扣率',
  `payment_terms` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '付款条款',
  `delivery_terms` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '交货条款',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `attr1` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr2` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr3` bigint(20) NULL DEFAULT NULL,
  `attr4` bigint(20) NULL DEFAULT NULL,
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  `select_flow_id` bigint(20) NULL DEFAULT NULL COMMENT '审批流程ID',
  `contract_id` bigint(20) NULL DEFAULT NULL COMMENT '合同ID，关联pu_contract表（预留字段）',
  `contract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同编号（预留字段）',
  `dept_id` bigint(20) NULL DEFAULT NULL COMMENT '采购部门ID（关联sys_dept）',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '采购部门名称',
  `buyer_id` bigint(20) NULL DEFAULT NULL COMMENT '采购员ID（关联sys_user）',
  `buyer_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '采购员名称',
  `certified_version` int(11) NULL DEFAULT NULL COMMENT '可信订单CAS版本；历史NULL不认证',
  `certified_terms_id` bigint(20) NULL DEFAULT NULL COMMENT '已独立确认的不可变报价版本ID',
  PRIMARY KEY (`order_id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no`, `tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2108407691577581571 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '采购订单表' ROW_FORMAT = Dynamic;

