-- ----------------------------
-- Table structure for pu_purchase_return
-- ----------------------------
DROP TABLE IF EXISTS `pu_purchase_return`;
CREATE TABLE `pu_purchase_return`  (
  `return_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '采购退货ID',
  `return_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '退货单号',
  `order_id` bigint(20) NULL DEFAULT NULL COMMENT '采购订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '采购订单号',
  `vendor_id` bigint(20) NULL DEFAULT NULL COMMENT '供应商ID',
  `vendor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `return_date` datetime(0) NULL DEFAULT NULL COMMENT '退货日期',
  `return_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '退货原因',
  `total_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '金额',
  `tax_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '税额',
  `amount_excluding_tax` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '不含税总金额',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `select_flow_id` bigint(20) NULL DEFAULT NULL COMMENT '已选审批流程模板ID',
  `attr1` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr2` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr3` bigint(20) NULL DEFAULT NULL,
  `attr4` bigint(20) NULL DEFAULT NULL,
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  PRIMARY KEY (`return_id`) USING BTREE,
  UNIQUE INDEX `uk_return_no`(`return_no`, `tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '采购退货表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for pu_purchase_return_line
-- ----------------------------
DROP TABLE IF EXISTS `pu_purchase_return_line`;
CREATE TABLE `pu_purchase_return_line`  (
  `line_id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '退货行ID',
  `return_id` bigint(20) NOT NULL COMMENT '退货单ID',
  `order_line_id` bigint(20) NULL DEFAULT NULL COMMENT '采购订单行ID',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位',
  `return_quantity` decimal(18, 4) NULL DEFAULT NULL COMMENT '退货数量',
  `unit_price` decimal(18, 4) NULL DEFAULT NULL COMMENT '单价',
  `tax_rate` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '税率',
  `amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '金额',
  `tax_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '行税额',
  `amount_excluding_tax` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '不含税行金额',
  `return_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '退货原因',
  `sort_order` int(11) NULL DEFAULT NULL COMMENT '排序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `attr1` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr2` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `attr3` bigint(20) NULL DEFAULT NULL,
  `attr4` bigint(20) NULL DEFAULT NULL,
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0',
  PRIMARY KEY (`line_id`) USING BTREE,
  INDEX `idx_return_id`(`return_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '采购退货行表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for pu_requirement_allocation_event
-- ----------------------------
DROP TABLE IF EXISTS `pu_requirement_allocation_event`;
CREATE TABLE `pu_requirement_allocation_event`  (
  `event_id` bigint(20) NOT NULL COMMENT '雪花ID，占用事件ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `allocation_id` bigint(20) NOT NULL COMMENT '对应来源占用账本ID',
  `event_sequence` int(11) NULL DEFAULT NULL COMMENT '占用内因果序号：CREATE=0，变更=账本CAS新版本；NULL旧事件未证明，禁止自动回填',
  `event_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事务内幂等事件键，不可复用',
  `event_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建/承接/部分入账/释放/补偿',
  `from_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原状态',
  `to_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '新状态',
  `occupied_base_before` decimal(18, 4) NOT NULL COMMENT '原基本单位阻断量',
  `occupied_base_after` decimal(18, 4) NOT NULL COMMENT '新基本单位阻断量',
  `requisition_line_id` bigint(20) NOT NULL COMMENT '申请行ID快照',
  `order_line_id` bigint(20) NULL DEFAULT NULL COMMENT '订单行ID快照',
  `actor_id` bigint(20) NULL DEFAULT NULL COMMENT '业务操作人ID；自动任务另行审计',
  `occurred_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '事件发生时间',
  PRIMARY KEY (`event_id`) USING BTREE,
  UNIQUE INDEX `uk_prae_tenant_event_key`(`tenant_id`, `event_key`) USING BTREE,
  UNIQUE INDEX `uk_prae_tenant_allocation_sequence`(`tenant_id`, `allocation_id`, `event_sequence`) USING BTREE,
  INDEX `idx_prae_tenant_allocation`(`tenant_id`, `allocation_id`, `occurred_at`) USING BTREE,
  INDEX `idx_prae_tenant_order_line`(`tenant_id`, `order_line_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '逐来源占用状态变更与释放不可覆盖审计' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pu_requirement_allocation_event
-- ----------------------------

-- ----------------------------
-- Table structure for pu_requirement_allocation_ledger
-- ----------------------------
DROP TABLE IF EXISTS `pu_requirement_allocation_ledger`;
CREATE TABLE `pu_requirement_allocation_ledger`  (
  `allocation_id` bigint(20) NOT NULL COMMENT '雪花ID，逐来源占用ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `material_id` bigint(20) NOT NULL COMMENT '物料ID',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显式来源类型，MRP_DETAIL；不可推断旧source_id',
  `detail_id` bigint(20) NOT NULL COMMENT '已核验的MRP需求明细ID',
  `requisition_line_id` bigint(20) NOT NULL COMMENT '采购申请行ID（ERP事务内写入）',
  `allocation_no` int(11) NOT NULL COMMENT '同来源与申请行的拆分序号，幂等不可复用',
  `order_line_id` bigint(20) NULL DEFAULT NULL COMMENT '继承来源的采购订单行ID，未转单为NULL',
  `base_uom_id` bigint(20) NOT NULL COMMENT '物料已核验基本单位ID',
  `covered_demand_base_qty` decimal(18, 4) NOT NULL COMMENT '本条来源分配的基本单位量，不含MOQ超额',
  `occupied_base_qty` decimal(18, 4) NOT NULL COMMENT '当前申请意图/晚到订单阻断量（基本单位）',
  `fulfilled_base_qty` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '已核验入账履约量（基本单位）',
  `released_base_qty` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '已核验释放量（基本单位）',
  `allocation_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'REQUEST_INTENT/ORDER_COMMITTED_NOT_TIMELY_SUPPLY/ORDER_TIMELY_SUPPLY/RELEASED',
  `allocation_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户内确定性的来源占用幂等键（含人工）',
  `decision_idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'AI动作幂等键；人工来源为NULL',
  `version` int(11) NOT NULL DEFAULT 0 COMMENT '行乐观锁版本；改写/释放需CAS',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建留痕',
  `transfer_time` datetime(0) NULL DEFAULT NULL COMMENT '最近一次订单承接时间',
  `released_at` datetime(0) NULL DEFAULT NULL COMMENT '最终释放时间；不能仅因申请关闭释放订单承接',
  `release_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '业务释放原因',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '最后一次业务状态变更时间',
  PRIMARY KEY (`allocation_id`) USING BTREE,
  UNIQUE INDEX `uk_pral_tenant_key`(`tenant_id`, `allocation_key`) USING BTREE,
  UNIQUE INDEX `uk_pral_tenant_req_detail_no`(`tenant_id`, `requisition_line_id`, `detail_id`, `allocation_no`) USING BTREE,
  INDEX `idx_pral_tenant_material`(`tenant_id`, `material_id`, `allocation_status`) USING BTREE,
  INDEX `idx_pral_tenant_detail`(`tenant_id`, `detail_id`) USING BTREE,
  INDEX `idx_pral_tenant_req_line`(`tenant_id`, `requisition_line_id`) USING BTREE,
  INDEX `idx_pral_tenant_order_line`(`tenant_id`, `order_line_id`) USING BTREE,
  INDEX `idx_pral_tenant_decision_key`(`tenant_id`, `decision_idempotency_key`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '逐MRP明细到申请行/订单行的基本单位占用账本' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pu_requirement_allocation_ledger
-- ----------------------------

-- ----------------------------
-- Table structure for pu_requirement_material_guard
-- ----------------------------
DROP TABLE IF EXISTS `pu_requirement_material_guard`;
CREATE TABLE `pu_requirement_material_guard`  (
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID',
  `material_id` bigint(20) NOT NULL COMMENT '物料ID',
  `version` int(11) NOT NULL DEFAULT 0 COMMENT '竞争池版本，由ERP事务内锁定后核验',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '最近一次事务变更时间',
  PRIMARY KEY (`tenant_id`, `material_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '采购同租户物料竞争池行锁（由业务事务创建并锁定）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pu_requirement_material_guard
-- ----------------------------

-- ----------------------------
-- Table structure for pu_vendor_evaluation
-- ----------------------------
DROP TABLE IF EXISTS `pu_vendor_evaluation`;
CREATE TABLE `pu_vendor_evaluation`  (
  `evaluation_id` bigint(20) NOT NULL COMMENT '评估ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `vendor_id` bigint(20) NOT NULL COMMENT '供应商ID',
  `vendor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `eval_period` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评估周期(如2026-05)',
  `delivery_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '交货及时率(%)',
  `quality_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '质量合格率(%)',
  `price_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '价格竞争力评分',
  `total_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '综合评分',
  `eval_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '评估等级(A/B/C/D)',
  `total_orders` int(11) NULL DEFAULT NULL COMMENT '评估期内总订单数',
  `on_time_orders` int(11) NULL DEFAULT NULL COMMENT '按时交货订单数',
  `total_received_qty` decimal(14, 4) NULL DEFAULT NULL COMMENT '总收货数量',
  `qualified_qty` decimal(14, 4) NULL DEFAULT NULL COMMENT '合格数量',
  `return_qty` decimal(14, 4) NULL DEFAULT NULL COMMENT '退货数量',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `attr1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `attr3` bigint(20) NULL DEFAULT NULL COMMENT '预留字段3',
  `attr4` bigint(20) NULL DEFAULT NULL COMMENT '预留字段4',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志(0存在 2删除)',
  PRIMARY KEY (`evaluation_id`) USING BTREE,
  UNIQUE INDEX `uk_vendor_period`(`vendor_id`, `eval_period`, `tenant_id`) USING BTREE,
  INDEX `idx_vendor`(`vendor_id`) USING BTREE,
  INDEX `idx_period`(`eval_period`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '供应商评估记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of pu_vendor_evaluation
-- ----------------------------

-- ----------------------------
-- Table structure for report_item
-- ----------------------------
DROP TABLE IF EXISTS `report_item`;
CREATE TABLE `report_item`  (
  `item_id` bigint(20) NOT NULL COMMENT '项目ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `report_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '报表类型 BALANCE-资产负债表 INCOME-利润表 CASH-现金流量表',
  `item_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目编码(如 BS_MONETARY)',
  `item_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称(如 货币资金)',
  `sort_order` int(11) NULL DEFAULT 0 COMMENT '显示顺序',
  `parent_item_id` bigint(20) NULL DEFAULT 0 COMMENT '父项目ID(分组行,0=顶级)',
  `is_summary` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否合计行 0-否 1-是(由子项汇总)',
  `account_code_match` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '科目编码匹配(逗号分隔;100% 结尾通配)',
  `sign` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '取值符号 1-正 -1-负',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '状态 0-正常 1-停用',
  `version` int(11) NULL DEFAULT 0 COMMENT '乐观锁版本号',
  `create_dept` bigint(20) NULL DEFAULT NULL,
  `create_by` bigint(20) NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint(20) NULL DEFAULT NULL,
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  PRIMARY KEY (`item_id`) USING BTREE,
  UNIQUE INDEX `uk_item`(`report_type`, `item_code`, `tenant_id`) USING BTREE,
  INDEX `idx_report_type`(`report_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '报表项目-科目映射' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of report_item
-- ----------------------------

-- ----------------------------
-- Table structure for sch_attendance
-- ----------------------------
DROP TABLE IF EXISTS `sch_attendance`;
CREATE TABLE `sch_attendance`  (
  `attendance_id` bigint(20) NOT NULL COMMENT '考勤记录ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `worker_id` bigint(20) NULL DEFAULT NULL COMMENT '人员ID',
  `worker_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人员姓名',
  `record_date` datetime(0) NULL DEFAULT NULL COMMENT '考勤日期',
  `schedule_id` bigint(20) NULL DEFAULT NULL COMMENT '关联排班ID',
  `clock_in_time` datetime(0) NULL DEFAULT NULL COMMENT '上班打卡时间',
  `clock_out_time` datetime(0) NULL DEFAULT NULL COMMENT '下班打卡时间',
  `late_minutes` bigint(20) NULL DEFAULT 0 COMMENT '迟到分钟数',
  `leave_early_minutes` bigint(20) NULL DEFAULT 0 COMMENT '早退分钟数',
  `overtime_hours` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '加班时长',
  `attendance_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '考勤结果: normal正常, late迟到, early_leave早退, absent旷工, leave请假',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '数据来源: manual手动, device设备同步',
  `device_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '打卡设备ID',
  `device_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备名称',
  `face_verify_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人脸验证状态: NONE未验证, PASS通过, FAIL失败',
  `face_verify_time` datetime(0) NULL DEFAULT NULL COMMENT '人脸验证时间',
  `face_similarity` decimal(5, 4) NULL DEFAULT NULL COMMENT '人脸相似度',
  `face_image_oss_id` bigint(20) NULL DEFAULT NULL COMMENT '打卡人脸照片ossId(MinIO存证)',
  `face_verify_attempts` int(11) NULL DEFAULT 0 COMMENT '人脸验证尝试次数(降级补跑计数,达上限后不再进入补跑候选集)',
  `face_verify_last_attempt_time` datetime(0) NULL DEFAULT NULL COMMENT '人脸验证最近一次尝试时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `clock_in_latitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '上班打卡纬度',
  `clock_in_longitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '上班打卡经度',
  `clock_in_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上班打卡地址/定位描述',
  `clock_in_accuracy` decimal(10, 2) NULL DEFAULT NULL COMMENT '上班打卡定位精度(米, 客户端上报; ERP-CV-05)',
  `clock_out_latitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '下班打卡纬度',
  `clock_out_longitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '下班打卡经度',
  `clock_out_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '下班打卡地址/定位描述',
  `clock_out_accuracy` decimal(10, 2) NULL DEFAULT NULL COMMENT '下班打卡定位精度(米, 客户端上报; ERP-CV-05)',
  PRIMARY KEY (`attendance_id`) USING BTREE,
  UNIQUE INDEX `uk_worker_date`(`tenant_id`, `worker_id`, `record_date`) USING BTREE,
  INDEX `idx_worker_id`(`worker_id`) USING BTREE,
  INDEX `idx_record_date`(`record_date`) USING BTREE,
  INDEX `idx_attendance_status`(`attendance_status`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE,
  INDEX `idx_face_verify_backfill`(`face_verify_status`, `face_verify_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '考勤记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sch_attendance
-- ----------------------------

-- ----------------------------
-- Table structure for sch_employee_schedule
-- ----------------------------
DROP TABLE IF EXISTS `sch_employee_schedule`;
CREATE TABLE `sch_employee_schedule`  (
  `schedule_id` bigint(20) NOT NULL COMMENT '员工排班ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `plan_id` bigint(20) NULL DEFAULT NULL COMMENT '排班计划ID',
  `worker_id` bigint(20) NULL DEFAULT NULL COMMENT '人员ID',
  `worker_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人员姓名',
  `team_id` bigint(20) NULL DEFAULT NULL COMMENT '班组ID',
  `team_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '班组名称',
  `shift_id` bigint(20) NULL DEFAULT NULL COMMENT '班次ID',
  `shift_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '班次名称',
  `scheduled_date` datetime(0) NULL DEFAULT NULL COMMENT '排班日期',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT '排班开始时间',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '排班结束时间',
  `actual_shift_id` bigint(20) NULL DEFAULT NULL COMMENT '实际班次ID（用于调班覆盖）',
  `schedule_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '排班状态',
  `is_working_day` tinyint(4) NULL DEFAULT 1 COMMENT '是否工作日 0:否 1:是',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `active_worker_date_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (if((`del_flag` = '0'),concat(`worker_id`,'#',cast(`scheduled_date` as date)),NULL)) VIRTUAL COMMENT '同一人同日活跃排班唯一键(逻辑删除行为 NULL,不参与唯一性)' NULL,
  PRIMARY KEY (`schedule_id`) USING BTREE,
  UNIQUE INDEX `uk_worker_date_active`(`tenant_id`, `active_worker_date_key`) USING BTREE,
  INDEX `idx_plan_id`(`plan_id`) USING BTREE,
  INDEX `idx_worker_id`(`worker_id`) USING BTREE,
  INDEX `idx_team_id`(`team_id`) USING BTREE,
  INDEX `idx_shift_id`(`shift_id`) USING BTREE,
  INDEX `idx_scheduled_date`(`scheduled_date`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '员工排班明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of sch_employee_schedule
-- ----------------------------

-- ----------------------------
-- Table structure for sch_holiday
