-- Records of wm_batch
-- ----------------------------

-- ----------------------------
-- Table structure for wm_certified_arrival_command
-- ----------------------------
DROP TABLE IF EXISTS `wm_certified_arrival_command`;
CREATE TABLE `wm_certified_arrival_command`  (
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原请求租户',
  `request_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原请求永久键',
  `request_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规范化原载荷摘要',
  `actor_id` bigint(20) NOT NULL COMMENT '服务端原创建操作人',
  `order_id` bigint(20) NOT NULL COMMENT '真实批准采购订单',
  `purchase_line_id` bigint(20) NOT NULL COMMENT '原采购订单行',
  `order_version` int(11) NOT NULL COMMENT '创建时批准版本',
  `notice_id` bigint(20) NOT NULL COMMENT '原通知业务头',
  `notice_line_id` bigint(20) NOT NULL COMMENT '原通知业务行',
  `notice_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '正常编号规则结果',
  `vendor_id` bigint(20) NOT NULL COMMENT '原采购供应商',
  `material_id` bigint(20) NOT NULL COMMENT '原正常物料',
  `base_uom_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原基本单位',
  `quantity` decimal(18, 4) NOT NULL COMMENT '原通知声明量，不新增采购额度',
  `arrival_date` date NOT NULL COMMENT '通知计划到货日',
  `notice_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原通知名称',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原说明',
  `create_time` datetime(3) NOT NULL COMMENT '原创建提交时点',
  PRIMARY KEY (`tenant_id`, `request_key`) USING BTREE,
  UNIQUE INDEX `uk_wm_certified_arrival`(`tenant_id`, `notice_id`) USING BTREE,
  UNIQUE INDEX `uk_wm_certified_arrival_line`(`tenant_id`, `notice_line_id`) USING BTREE,
  INDEX `idx_wm_certified_arrival_source`(`tenant_id`, `order_id`, `purchase_line_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '认证订单独立到货原生创建命令，不补历史' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wm_certified_arrival_command
-- ----------------------------

-- ----------------------------
-- Table structure for wm_certified_iqc_evidence
-- ----------------------------
DROP TABLE IF EXISTS `wm_certified_iqc_evidence`;
CREATE TABLE `wm_certified_iqc_evidence`  (
  `evidence_id` bigint(20) NOT NULL COMMENT 'ERP不可变IQC证据ID',
  `tenant_id` varchar(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '真实消息与MES/ERP一致租户',
  `inspection_id` bigint(20) NOT NULL COMMENT '真实MES qc_iqc.iqc_id',
  `inspection_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '真实MES IQC编号',
  `receive_id` bigint(20) NOT NULL COMMENT '原真实ERP收货单',
  `material_id` bigint(20) NOT NULL COMMENT '原收货全物料范围',
  `base_uom_id` bigint(20) NOT NULL COMMENT 'V1观察单位不授权；V2仅取实际创建时原生出生单位',
  `quantity_scale` tinyint(3) UNSIGNED NOT NULL COMMENT '已核可信本单位精度；此来源仅支持0至4',
  `inspected_quantity` decimal(14, 4) NOT NULL COMMENT 'MES真实检验量；须等于原收货同料全量',
  `inspect_result` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '真实QUALIFIED或UNQUALIFIED',
  `inspector_id` bigint(20) NOT NULL COMMENT '真实MES完成检验员',
  `source_kind` varchar(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'V1无原单位证明；V2须重读原生出生登记与绑定',
  `source_version` varchar(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'QC_IQC_CURRENT_V1与实际数据主体摘要',
  `actual_body_sha256` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'MES原始当前单头及明细完整数据主体摘要',
  `receipt_scope_sha256` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '原ERP收货同料全行数量单位来源摘要',
  `evidence_sha256` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '本不可变证据字段完整性摘要',
  `first_message_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '首个真实消息标识；不是质量授权',
  `source_created_at` datetime(3) NOT NULL COMMENT 'MES真实创建时间',
  `completed_at` datetime(3) NOT NULL COMMENT 'MES真实检验完成时间',
  `source_updated_at` datetime(3) NULL DEFAULT NULL COMMENT 'MES当前更新时间；无乐观版本列不据此猜最新',
  `observed_at` datetime(3) NOT NULL COMMENT '独立MES只读可重复读事务观察完成时间',
  `certified_at` datetime(3) NOT NULL COMMENT '独立ERP自主管理的可重复读事务证据落账时间',
  `birth_id` bigint(20) NULL DEFAULT NULL COMMENT '真实新建IQC的ERP永久出生登记，历史NULL不认证',
  `birth_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原生出生登记摘要，历史NULL不授权',
  PRIMARY KEY (`evidence_id`) USING BTREE,
  UNIQUE INDEX `uk_certified_iqc_inspection`(`tenant_id`, `inspection_id`) USING BTREE,
  UNIQUE INDEX `uk_certified_iqc_scope`(`tenant_id`, `receive_id`, `material_id`) USING BTREE,
  UNIQUE INDEX `uk_certified_iqc_message`(`tenant_id`, `first_message_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'MES真实完成来源的ERP不可变IQC证据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wm_certified_iqc_evidence
-- ----------------------------

-- ----------------------------
-- Table structure for wm_certified_receipt_posting
-- ----------------------------
DROP TABLE IF EXISTS `wm_certified_receipt_posting`;
CREATE TABLE `wm_certified_receipt_posting`  (
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '明确当前租户',
  `receive_id` bigint(20) NOT NULL COMMENT '真实原入库单，永久幂等身份',
  `material_id` bigint(20) NOT NULL,
  `actor_id` bigint(20) NOT NULL,
  `source_fingerprint` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结真实来源摘要，不是上传的核验布尔',
  `total_quantity` decimal(18, 4) NOT NULL,
  `posted_at` datetime(0) NULL,
  `notification_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PENDING/ENQUEUED，接受不等于消费者完成',
  PRIMARY KEY (`tenant_id`, `receive_id`) USING BTREE,
  INDEX `idx_certified_receipt_material`(`tenant_id`, `material_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '原生精确收货过账结果与提交后通知恢复' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of wm_certified_receipt_posting
-- ----------------------------

-- ----------------------------
-- Table structure for wm_certified_receive_command
-- ----------------------------
DROP TABLE IF EXISTS `wm_certified_receive_command`;
CREATE TABLE `wm_certified_receive_command`  (
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请求租户',
  `request_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原请求永久键',
  `request_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规范化原载荷摘要',
  `actor_id` bigint(20) NOT NULL COMMENT '原创建操作人',
  `order_id` bigint(20) NOT NULL COMMENT '批准采购订单',
  `purchase_line_id` bigint(20) NOT NULL COMMENT '明确采购订单行',
  `receive_id` bigint(20) NOT NULL COMMENT '原生收货单',
  `line_id` bigint(20) NOT NULL COMMENT '原生收货行',
  `receive_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务端规则编号',
  `material_id` bigint(20) NOT NULL COMMENT '原物料',
  `base_uom_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原基本单位',
  `quantity` decimal(18, 4) NOT NULL COMMENT '明确实际到货数量',
  `arrival_date` date NOT NULL COMMENT '实际到货日期',
  `warehouse_id` bigint(20) NOT NULL COMMENT '仓库',
  `area_id` bigint(20) NOT NULL COMMENT '库区',
  `location_id` bigint(20) NOT NULL COMMENT '储位',
  `create_time` datetime(3) NOT NULL COMMENT '提交创建时间',
  `notice_id` bigint(20) NULL DEFAULT NULL COMMENT '原认证通知引用，历史不回填',
  `notice_line_id` bigint(20) NULL DEFAULT NULL COMMENT '原认证通知引用，历史不回填',
  PRIMARY KEY (`tenant_id`, `request_key`) USING BTREE,
  UNIQUE INDEX `uk_wm_certified_receive`(`tenant_id`, `receive_id`, `line_id`) USING BTREE,
  INDEX `idx_wm_certified_order_line`(`tenant_id`, `order_id`, `purchase_line_id`) USING BTREE,
  INDEX `idx_wm_certified_arrival_ref`(`tenant_id`, `notice_id`, `notice_line_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '认证采购原生收货创建永久请求' ROW_FORMAT = Dynamic;

