-- Records of wm_certified_receive_command
-- ----------------------------

-- ----------------------------
-- Table structure for wm_document_sn
-- ----------------------------
DROP TABLE IF EXISTS `wm_document_sn`;
CREATE TABLE `wm_document_sn`  (
  `document_sn_id` bigint(20) NOT NULL COMMENT '单据实物明细ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `command_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '幂等业务命令ID',
  `line_no` bigint(20) NOT NULL COMMENT '命令内稳定行号',
  `source_doc_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '来源单据类型',
  `source_doc_id` bigint(20) NOT NULL COMMENT '来源单据ID',
  `source_doc_line_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '来源单据行ID',
  `detail_version` bigint(20) NOT NULL DEFAULT 1 COMMENT '提交时单据明细版本',
  `identity_id` bigint(20) NOT NULL COMMENT '正式实物身份',
  `material_id` bigint(20) NOT NULL COMMENT '物料ID',
  `batch_id` bigint(20) NULL DEFAULT NULL COMMENT 'ERP批次ID',
  `source_stock_id` bigint(20) NULL DEFAULT NULL COMMENT '来源库存ID',
  `target_location_id` bigint(20) NULL DEFAULT NULL COMMENT '目标储位ID',
  `original_tx_id` bigint(20) NULL DEFAULT NULL COMMENT '退回或冲正所引用的原事务ID',
  `posting_group_id` bigint(20) NULL DEFAULT NULL COMMENT '过账证明组ID',
  `quantity` decimal(18, 4) NOT NULL DEFAULT 1.0000 COMMENT '基本单位数量，SN行由服务校验为1',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`document_sn_id`) USING BTREE,
  UNIQUE INDEX `uk_document_sn_command_line`(`tenant_id`, `command_id`, `line_no`) USING BTREE,
  UNIQUE INDEX `uk_document_sn_version_identity`(`tenant_id`, `source_doc_type`, `source_doc_id`, `source_doc_line_id`, `detail_version`, `identity_id`) USING BTREE,
  INDEX `idx_document_sn_identity`(`tenant_id`, `identity_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '版本化单据实物明细，不改写历史凭据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_material_handover
-- ----------------------------
DROP TABLE IF EXISTS `wm_material_handover`;
CREATE TABLE `wm_material_handover`  (
  `handover_id` bigint(20) NOT NULL COMMENT '交接单ID',
  `handover_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交接单号',
  `wo_id` bigint(20) NULL DEFAULT NULL COMMENT '来源工单ID(prd_work_order)',
  `wo_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源工单号',
  `warehouse_id` bigint(20) NULL DEFAULT NULL COMMENT '源仓库ID',
  `warehouse_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '源仓库编码',
  `warehouse_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '源仓名称',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态: DRAFT 待签收 / SIGNED 已签收',
  `handover_time` datetime(0) NULL DEFAULT NULL COMMENT '交接时间(建单时间)',
  `sign_by` bigint(20) NULL DEFAULT NULL COMMENT '签收人ID',
  `sign_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '签收人',
  `sign_time` datetime(0) NULL DEFAULT NULL COMMENT '签收时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志(0存在 2删除)',
  PRIMARY KEY (`handover_id`) USING BTREE,
  UNIQUE INDEX `uk_handover_no`(`handover_no`, `tenant_id`) USING BTREE,
  INDEX `idx_handover_status`(`status`) USING BTREE,
  INDEX `idx_handover_wo_no`(`wo_no`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '上料交接单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_material_handover_line
-- ----------------------------
DROP TABLE IF EXISTS `wm_material_handover_line`;
CREATE TABLE `wm_material_handover_line`  (
  `line_id` bigint(20) NOT NULL COMMENT '行ID',
  `handover_id` bigint(20) NOT NULL COMMENT '交接单ID',
  `material_id` bigint(20) NOT NULL COMMENT '物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规格型号',
  `base_uom_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '基本单位',
  `base_uom_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '基本单位名称',
  `batch_id` bigint(20) NULL DEFAULT NULL COMMENT '批次ID',
  `batch_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '批次号',
  `from_location_id` bigint(20) NULL DEFAULT NULL COMMENT '源库位ID(源仓库内)',
  `from_location_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '源库位编码',
  `from_location_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '源库位名称',
  `to_location_id` bigint(20) NULL DEFAULT NULL COMMENT '线边库位ID',
  `to_location_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '线边库位编码',
  `to_location_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '线边库位名称',
  `quantity` decimal(18, 4) NULL DEFAULT NULL COMMENT '计划交接数量',
  `actual_qty` decimal(18, 4) NULL DEFAULT NULL COMMENT '实交数量(PDA核销累计)',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志(0存在 2删除)',
  PRIMARY KEY (`line_id`) USING BTREE,
  INDEX `idx_handover_line_handover`(`handover_id`) USING BTREE,
  INDEX `idx_handover_line_material`(`material_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '上料交接单行' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_material_receive
-- ----------------------------
DROP TABLE IF EXISTS `wm_material_receive`;
CREATE TABLE `wm_material_receive`  (
  `receive_id` bigint(20) NOT NULL COMMENT '入库单ID',
  `receive_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '入库单编号',
  `receive_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '入库单名称',
  `iqc_id` bigint(20) NULL DEFAULT NULL COMMENT '来料检验单ID',
  `iqc_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来料检验单编号',
  `iqc_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来料检验结论: QUALIFIED/UNQUALIFIED(无到货通知时上架门禁依据)',
  `notice_id` bigint(20) NULL DEFAULT NULL COMMENT '到货通知单ID',
  `notice_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '到货通知单编号',
  `pur_id` bigint(20) NULL DEFAULT NULL COMMENT '采购订单ID',
  `pur_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '采购订单编号',
  `vendor_id` bigint(20) NULL DEFAULT NULL COMMENT '供应商ID',
  `vendor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `vendor_nick` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商简称',
  `warehouse_id` bigint(20) NULL DEFAULT NULL COMMENT '仓库ID',
  `warehouse_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '仓库编码',
  `warehouse_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '仓库名称',
  `area_id` bigint(20) NULL DEFAULT NULL COMMENT '库区ID',
  `area_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '库区编码',
  `area_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '库区名称',
  `location_id` bigint(20) NULL DEFAULT NULL COMMENT '库位ID',
  `location_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '库位编码',
  `location_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '库位名称',
  `receive_date` datetime(0) NULL DEFAULT NULL COMMENT '入库日期',
  `status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '单据状态',
  `select_flow_id` bigint(20) NULL DEFAULT NULL COMMENT '已选审批流程模板（wf_custom_form.id）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '备注',
  `attr1` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `attr3` int(11) NULL DEFAULT 0 COMMENT '预留字段3',
  `attr4` int(11) NULL DEFAULT 0 COMMENT '预留字段4',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `shelf_by` bigint(20) NULL DEFAULT NULL COMMENT '上架人ID',
  `shelf_time` datetime(0) NULL DEFAULT NULL COMMENT '上架时间',
  PRIMARY KEY (`receive_id`) USING BTREE,
  INDEX `idx_receive_status`(`status`) USING BTREE,
  INDEX `idx_receive_vendor`(`vendor_id`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '物料入库单表' ROW_FORMAT = Dynamic;

