CREATE TABLE `wm_misc_recpt`  (
  `recpt_id` bigint(20) NOT NULL COMMENT '杂项入库ID',
  `recpt_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '入库单号',
