  INDEX `idx_warehouse`(`warehouse_id`) USING BTREE,
  INDEX `idx_wm_production_recpt_batch_id`(`batch_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2108738647677165570 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '生产完工入库表' ROW_FORMAT = Dynamic;

