-- ----------------------------
-- Table structure for wm_receipt_iqc_birth
-- ----------------------------
DROP TABLE IF EXISTS `wm_receipt_iqc_birth`;
CREATE TABLE `wm_receipt_iqc_birth`  (
  `birth_id` bigint(20) NOT NULL COMMENT 'ERP服务器生成的永久出生身份',
  `tenant_id` varchar(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '真实租户',
  `receive_id` bigint(20) NOT NULL COMMENT '真实收货头',
  `material_id` bigint(20) NOT NULL COMMENT '真实物料范围',
  `base_uom_id` bigint(20) NOT NULL COMMENT '创建新检验前冻结的真实原数量单位',
  `quantity_scale` tinyint(3) UNSIGNED NOT NULL COMMENT '出生时已核原单位精度',
  `quantity` decimal(14, 4) NOT NULL COMMENT '出生时完整同物料原生收货量',
  `receipt_scope_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出生时真实头和全部行范围摘要',
  `birth_sha256` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '全部登记事实完整性摘要，不是DTO授权',
  `captured_at` bigint(20) NOT NULL COMMENT '实际ERP捕获时点毫秒，非客户端时间',
  `receive_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '真实收货编号',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '真实物料编码',
  `material_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '真实物料名称',
  `vendor_id` bigint(20) NOT NULL COMMENT '真实供应商身份',
  `vendor_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '真实供应商名称',
  PRIMARY KEY (`birth_id`) USING BTREE,
  UNIQUE INDEX `uk_iqc_birth_scope`(`tenant_id`, `receive_id`, `material_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '永久IQC创建时单位与范围准备事实' ROW_FORMAT = Dynamic;

