  `location_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库位名称',
  `warehouse_id` bigint(20) NULL DEFAULT NULL COMMENT '仓库ID',
