-- ----------------------------
-- Table structure for wm_subcontract_receive
-- ----------------------------
DROP TABLE IF EXISTS `wm_subcontract_receive`;
CREATE TABLE `wm_subcontract_receive`  (
  `receive_id` bigint(20) NOT NULL COMMENT '收货单ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `receive_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收货单号',
  `subcontract_id` bigint(20) NOT NULL COMMENT '委外订单ID',
  `subcontract_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '委外单号(冗余)',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '产出物料ID',
  `material_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `material_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `material_spec` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规格型号',
  `base_uom_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位名称',
  `vendor_id` bigint(20) NULL DEFAULT NULL COMMENT '供应商ID',
  `vendor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商编码',
  `vendor_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `target_warehouse_id` bigint(20) NULL DEFAULT NULL COMMENT '入库仓库ID(默认半成品仓)',
  `target_warehouse_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '入库仓库编码',
  `target_warehouse_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '入库仓库名称',
  `target_location_id` bigint(20) NULL DEFAULT NULL COMMENT '入库库位ID',
  `received_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '收货数量',
  `vendor_batch_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '外协批次号',
  `sn_scope` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'SN范围记录(如 SN-SC...0001-SN-SC...0100)',
  `receive_date` datetime(0) NULL DEFAULT NULL COMMENT '收货日期',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '状态: DRAFT草稿/POSTED已过账',
  `receiver_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收货人',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`receive_id`) USING BTREE,
  UNIQUE INDEX `uk_sc_receive_no`(`tenant_id`, `receive_no`) USING BTREE,
  INDEX `idx_sc_receive_subcontract`(`subcontract_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '委外收货单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_trace_audit_run
-- ----------------------------
DROP TABLE IF EXISTS `wm_trace_audit_run`;
CREATE TABLE `wm_trace_audit_run`  (
  `audit_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '审计工件ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `material_id` bigint(20) NULL DEFAULT NULL COMMENT '审计物料，未限定时为空',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'REVIEW_REQUIRED' COMMENT '只读审计结论状态，不修改原业务',
  `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '审计摘要',
  `report_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '完整审计报告工件',
  `content_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '审计报告原始UTF8字节SHA256',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`audit_id`) USING BTREE,
  INDEX `idx_trace_audit_tenant_created`(`tenant_id`, `created_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '物料追溯审计工件，只追加报告不改原业务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_trace_inbox
-- ----------------------------
DROP TABLE IF EXISTS `wm_trace_inbox`;
CREATE TABLE `wm_trace_inbox`  (
  `event_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '跨库稳定事件ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `source_module` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '事件源模块',
  `aggregate_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '来源业务聚合类型',
  `aggregate_id` bigint(20) NOT NULL COMMENT '来源业务聚合ID',
  `aggregate_version` bigint(20) NOT NULL COMMENT '同来源聚合单调版本',
  `event_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件类型',
  `schema_version` int(11) NOT NULL DEFAULT 1 COMMENT '消息契约版本',
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始冻结载荷JSON，禁止重试时重新计算',
  `content_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '原始载荷UTF8字节SHA256',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NEW' COMMENT 'NEW、WAITING、BROKER_SENT、APPLIED或CONFLICT状态',
  `attempts` int(11) NOT NULL DEFAULT 0 COMMENT '已尝试次数',
  `next_attempt_at` datetime(0) NULL DEFAULT NULL COMMENT '下次可重试时间，ACK重新激活时允许空值',
  `lease_owner` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '当前租约持有者',
  `lease_until` datetime(0) NULL DEFAULT NULL COMMENT '租约截止时间',
  `last_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '脱敏后的最近错误',
  `result_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '幂等消费结果JSON',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `applied_at` datetime(0) NULL DEFAULT NULL COMMENT '成功应用时间',
  PRIMARY KEY (`event_id`) USING BTREE,
  UNIQUE INDEX `uk_trace_event_stream_version`(`tenant_id`, `source_module`, `aggregate_type`, `aggregate_id`, `aggregate_version`) USING BTREE,
  INDEX `idx_trace_event_retry`(`status`, `next_attempt_at`, `lease_until`) USING BTREE,
  INDEX `idx_trace_event_tenant`(`tenant_id`, `created_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '本数据源事务内冻结的追溯幂等收件箱' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_trace_material_consumption
-- ----------------------------
DROP TABLE IF EXISTS `wm_trace_material_consumption`;
CREATE TABLE `wm_trace_material_consumption`  (
  `consumption_id` bigint(20) NOT NULL COMMENT 'ERP实际消耗接收记录ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `manifest_id` bigint(20) NOT NULL COMMENT '原MES完工清单ID',
  `manifest_revision` int(11) NOT NULL COMMENT '原清单修订',
  `allocation_id` bigint(20) NOT NULL COMMENT '原实际消耗lt_wo_consumption.consumption_id，不是额度分配ID',
  `erp_wo_id` bigint(20) NOT NULL COMMENT '原ERP生产工单',
  `material_id` bigint(20) NOT NULL COMMENT '实际组件物料ID',
  `reservation_id` bigint(20) NULL DEFAULT NULL COMMENT '原实际库存预留头',
  `reservation_line_id` bigint(20) NULL DEFAULT NULL COMMENT '原实际库存预留行',
  `posting_group_id` bigint(20) NULL DEFAULT NULL COMMENT '原发料过账证明组',
  `identity_id` bigint(20) NULL DEFAULT NULL COMMENT 'ERP正式组件身份',
  `source_stock_id` bigint(20) NULL DEFAULT NULL COMMENT '实际来源库存行',
  `erp_batch_id` bigint(20) NULL DEFAULT NULL COMMENT 'ERP批次ID，SN-only来源允许空值',
  `quantity` decimal(18, 4) NOT NULL COMMENT '实际消耗基本单位数量',
  `source_version` bigint(20) NOT NULL COMMENT 'MES冻结的实际来源版本',
  `evidence_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '原实际来源证据SHA256',
  `source_event_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ERP原授权或过账事件ID',
  PRIMARY KEY (`consumption_id`) USING BTREE,
  UNIQUE INDEX `uk_material_consumption_allocation`(`tenant_id`, `manifest_id`, `manifest_revision`, `allocation_id`) USING BTREE,
  INDEX `idx_material_consumption_wo`(`tenant_id`, `erp_wo_id`, `material_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP按原MES实际消耗分配接收，不按BOM推算' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_trace_material_reservation
-- ----------------------------
DROP TABLE IF EXISTS `wm_trace_material_reservation`;
CREATE TABLE `wm_trace_material_reservation`  (
  `reservation_id` bigint(20) NOT NULL COMMENT '实际库存预留ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `command_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '幂等业务命令ID',
  `erp_wo_id` bigint(20) NOT NULL COMMENT '原ERP生产工单',
  `mes_wo_id` bigint(20) NOT NULL COMMENT '原MES生产工单',
  `requirement_detail_id` bigint(20) NOT NULL COMMENT '原确认物料需求行',
  `material_id` bigint(20) NOT NULL COMMENT '预留组件物料ID',
  `policy_version` bigint(20) NOT NULL COMMENT '授权时物料追踪策略版本',
  `quantity` decimal(18, 4) NOT NULL COMMENT '实际预留合计数量',
  `content_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '原命令和实际选择的规范摘要',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RESERVED' COMMENT 'RESERVED预留或CONSUMED完工核销',
  PRIMARY KEY (`reservation_id`) USING BTREE,
  UNIQUE INDEX `uk_material_reservation_command`(`tenant_id`, `command_id`) USING BTREE,
  INDEX `idx_material_reservation_wo`(`tenant_id`, `erp_wo_id`, `status`) USING BTREE,
  INDEX `idx_material_reservation_requirement`(`tenant_id`, `requirement_detail_id`, `status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP倒冲实际库存预留头，与原库存同事务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_trace_material_reservation_line
-- ----------------------------
DROP TABLE IF EXISTS `wm_trace_material_reservation_line`;
CREATE TABLE `wm_trace_material_reservation_line`  (
  `reservation_line_id` bigint(20) NOT NULL COMMENT '实际库存预留行ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `reservation_id` bigint(20) NOT NULL COMMENT '原预留头ID',
  `line_no` bigint(20) NOT NULL COMMENT '原命令内预留行号',
  `source_stock_id` bigint(20) NOT NULL COMMENT '实际选定的原库存行',
  `identity_id` bigint(20) NULL DEFAULT NULL COMMENT 'ERP正式组件身份',
  `erp_batch_id` bigint(20) NULL DEFAULT NULL COMMENT 'ERP批次ID，SN-only来源允许空值',
  `valuation_group_id` bigint(20) NULL DEFAULT NULL COMMENT '原库存计价组，不按SN重新计价',
  `quantity` decimal(18, 4) NOT NULL COMMENT '本行实际预留数量',
  `consumed_quantity` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '完工实际核销数量',
  `version` bigint(20) NOT NULL DEFAULT 1 COMMENT '原预留行并发版本',
  PRIMARY KEY (`reservation_line_id`) USING BTREE,
  UNIQUE INDEX `uk_material_reservation_line`(`tenant_id`, `reservation_id`, `line_no`) USING BTREE,
  INDEX `idx_material_reservation_stock`(`tenant_id`, `source_stock_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ERP实际预留库存明细，保留正式组件与批次证据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_trace_outbox
-- ----------------------------
DROP TABLE IF EXISTS `wm_trace_outbox`;
CREATE TABLE `wm_trace_outbox`  (
  `event_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '跨库稳定事件ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `source_module` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '事件源模块',
  `aggregate_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '来源业务聚合类型',
  `aggregate_id` bigint(20) NOT NULL COMMENT '来源业务聚合ID',
  `aggregate_version` bigint(20) NOT NULL COMMENT '同来源聚合单调版本',
  `event_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件类型',
  `schema_version` int(11) NOT NULL DEFAULT 1 COMMENT '消息契约版本',
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始冻结载荷JSON，禁止重试时重新计算',
  `content_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '原始载荷UTF8字节SHA256',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NEW' COMMENT 'NEW、WAITING、BROKER_SENT、APPLIED或CONFLICT状态',
  `attempts` int(11) NOT NULL DEFAULT 0 COMMENT '已尝试次数',
  `next_attempt_at` datetime(0) NULL DEFAULT NULL COMMENT '下次可重试时间，ACK重新激活时允许空值',
  `lease_owner` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '当前租约持有者',
  `lease_until` datetime(0) NULL DEFAULT NULL COMMENT '租约截止时间',
  `last_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '脱敏后的最近错误',
  `result_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '幂等消费结果JSON',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `applied_at` datetime(0) NULL DEFAULT NULL COMMENT '成功应用时间',
  PRIMARY KEY (`event_id`) USING BTREE,
  UNIQUE INDEX `uk_trace_event_stream_version`(`tenant_id`, `source_module`, `aggregate_type`, `aggregate_id`, `aggregate_version`) USING BTREE,
  INDEX `idx_trace_event_retry`(`status`, `next_attempt_at`, `lease_until`) USING BTREE,
  INDEX `idx_trace_event_tenant`(`tenant_id`, `created_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '本数据源事务内冻结的追溯发件箱' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_trace_posting_group
-- ----------------------------
DROP TABLE IF EXISTS `wm_trace_posting_group`;
CREATE TABLE `wm_trace_posting_group`  (
  `posting_group_id` bigint(20) NOT NULL COMMENT '过账证明组ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `command_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '幂等业务命令ID',
  `source_doc_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '来源单据类型',
  `source_doc_id` bigint(20) NOT NULL COMMENT '来源单据ID',
  `source_doc_line_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '来源单据行ID',
  `detail_version` bigint(20) NOT NULL DEFAULT 1 COMMENT '冻结明细版本',
  `tx_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '库存业务类型',
  `material_id` bigint(20) NOT NULL COMMENT '物料ID',
  `valuation_group_id` bigint(20) NULL DEFAULT NULL COMMENT '原计价组ID',
  `quantity` decimal(18, 4) NOT NULL COMMENT '冻结基本单位数量',
  `amount` decimal(18, 4) NOT NULL COMMENT '冻结四位金额，单件拆分合计保持不变',
  `fingerprint` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '幂等请求摘要',
  `content_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '冻结明细内容摘要',
  `source_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '冻结原业务单据行内容摘要，不补造历史来源',
  `policy_version` bigint(20) NOT NULL COMMENT '冻结时物料追踪策略版本，不推定旧证明版本',
  `original_posting_group_id` bigint(20) NULL DEFAULT NULL COMMENT '补偿所引用的原过账组ID',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PREPARED' COMMENT '过账状态',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`posting_group_id`) USING BTREE,
  UNIQUE INDEX `uk_trace_posting_command`(`tenant_id`, `command_id`) USING BTREE,
  UNIQUE INDEX `uk_trace_posting_document_version`(`tenant_id`, `source_doc_type`, `source_doc_id`, `source_doc_line_id`, `detail_version`, `tx_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '原子库存过账证明，补偿另建新组' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_trace_repair_item
-- ----------------------------
DROP TABLE IF EXISTS `wm_trace_repair_item`;
CREATE TABLE `wm_trace_repair_item`  (
  `run_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '修复运行ID',
  `item_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '计划内修复项ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `target_table` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '白名单目标表',
  `target_key` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包含租户的完整主键JSON',
  `before_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修复前完整行JSON',
  `after_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修复后完整行JSON',
  `evidence_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '冻结来源凭据及审核依据JSON',
  `before_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '修复前规范行摘要，CAS比较依据',
  `after_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '修复后规范行摘要',
  `evidence_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '证据摘要',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PLANNED' COMMENT '修复项状态',
  `version` bigint(20) NOT NULL DEFAULT 1 COMMENT '修复项CAS版本',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`run_id`, `item_id`) USING BTREE,
  INDEX `idx_trace_repair_target`(`tenant_id`, `target_table`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '历史修复前后镜像与证据，不覆盖原业务凭据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_trace_repair_run
-- ----------------------------
DROP TABLE IF EXISTS `wm_trace_repair_run`;
CREATE TABLE `wm_trace_repair_run`  (
  `run_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '修复运行ID',
  `target_database` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显式核实的目标业务库',
  `target_environment` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '环境标识，不保存口令或连接串',
  `backup_reference` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '已核实的离线备份引用',
  `plan_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '批准计划摘要',
  `before_snapshot_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '完整修复前导出摘要',
  `after_snapshot_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '离线预演结果摘要',
  `journal_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '批准运行日志摘要',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PLANNED' COMMENT 'PLANNED、APPLIED、REVERTED或待补偿',
  `version` bigint(20) NOT NULL DEFAULT 1 COMMENT '运行状态CAS版本',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`run_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '本数据源历史修复运行日志，跨库不伪装原子事务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_trace_stock_conversion_run
-- ----------------------------
DROP TABLE IF EXISTS `wm_trace_stock_conversion_run`;
CREATE TABLE `wm_trace_stock_conversion_run`  (
  `run_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '当前库存转换运行ID，不重用已回退运行',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `material_id` bigint(20) NOT NULL COMMENT '整物料当前库存转换范围',
  `target_database` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显式核实的ERP目标库',
  `target_environment` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显式核实的目标环境',
  `backup_reference` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作者核实的备份引用，不含连接凭据',
  `cutover_at` datetime(0) NOT NULL COMMENT '真实physical census切点，不代表补造历史收货',
  `plan_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '批准转换计划摘要',
  `before_snapshot_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '完整转换前快照摘要',
  `after_snapshot_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '完整转换后快照摘要',
  `bridge_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'census当前身份桥摘要，保留原聚合流水',
  `journal_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '不可变完整转换日志，不含journal_hash自身；回退不覆盖',
  `journal_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '原完整日志原始UTF8字节SHA256，回退保持原值',
  `revert_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL COMMENT '实际回退日志摘要，未回退保持NULL',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PREPARED' COMMENT '同事务PREPARED到APPLIED，安全回退后REVERTED',
  `version` bigint(20) NOT NULL DEFAULT 1 COMMENT '审计状态CAS，回退后为2',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`run_id`) USING BTREE,
  INDEX `idx_stock_conversion_material`(`tenant_id`, `material_id`, `created_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '当前库存到正式SN的零损益转换审计，仅追加工件并CAS状态' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_transfer
-- ----------------------------
DROP TABLE IF EXISTS `wm_transfer`;
CREATE TABLE `wm_transfer`  (
  `transfer_id` bigint(20) NOT NULL COMMENT '调拨单ID',
  `transfer_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '调拨单号',
  `from_warehouse_id` bigint(20) NULL DEFAULT NULL COMMENT '来源仓库ID',
  `from_warehouse_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源仓库编码',
  `from_warehouse_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源仓库名称',
  `from_area_id` bigint(20) NULL DEFAULT NULL COMMENT '来源库区ID',
  `from_area_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源库区编码',
  `from_area_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源库区名称',
  `to_warehouse_id` bigint(20) NULL DEFAULT NULL COMMENT '目标仓库ID',
  `to_warehouse_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标仓库编码',
  `to_warehouse_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标仓库名称',
  `to_area_id` bigint(20) NULL DEFAULT NULL COMMENT '目标库区ID',
  `to_area_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标库区编码',
  `to_area_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标库区名称',
  `transfer_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '调拨类型',
  `total_quantity` decimal(18, 4) NULL DEFAULT NULL COMMENT '总数量',
  `status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT '状态',
  `operator_id` bigint(20) NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作人',
  `transfer_date` datetime(0) NULL DEFAULT NULL COMMENT '调拨日期',
  `execute_date` datetime(0) NULL DEFAULT NULL COMMENT '执行日期',
  `select_flow_id` bigint(20) NULL DEFAULT NULL COMMENT '已选审批流ID(wf_custom_form.id)',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '备注',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`transfer_id`) USING BTREE,
  UNIQUE INDEX `uk_transfer_no`(`transfer_no`, `tenant_id`) USING BTREE,
  INDEX `idx_transfer_status`(`status`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '库存调拨单表' ROW_FORMAT = Dynamic;

