-- ----------------------------
-- Table structure for wm_work_order_policy_adoption
-- ----------------------------
DROP TABLE IF EXISTS `wm_work_order_policy_adoption`;
CREATE TABLE `wm_work_order_policy_adoption`  (
  `adoption_id` bigint(20) NOT NULL COMMENT '已独立审批的采纳申请ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `command_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '幂等业务命令ID',
  `erp_wo_id` bigint(20) NOT NULL COMMENT '真实在途ERP工单ID',
  `expected_wo_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '已核实WO/BOM/需求来源预览摘要',
  `source_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '完整原始策略归档集合，不使用当前主数据',
  `source_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '原始策略归档字节摘要',
  `approval_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '独立审核人对原申请意图的批准工件',
  `approval_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '原批准工件字节摘要',
  `request_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '工单来源、原策略、双方操作人及审批时间窗的长度分帧摘要',
  `proposed_by` bigint(20) NOT NULL COMMENT '明确申请人，与批准人不同',
  `approved_by` bigint(20) NOT NULL COMMENT '独立批准人',
  `approved_at` datetime(3) NOT NULL COMMENT '原批准时间',
  `expires_at` datetime(3) NOT NULL COMMENT '批准有效期截止，过期拒绝',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_REVIEW' COMMENT '只有显式独立批准后才可APPROVED，实际服务CAS到APPLIED',
  `version` bigint(20) NOT NULL DEFAULT 1 COMMENT '批准/执行版本CAS',
  `applied_at` datetime(3) NULL DEFAULT NULL COMMENT '实际执行后未来生效时间，不回填历史生效',
  `snapshot_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL COMMENT '实际服务冻结后的整组策略摘要，未执行保持NULL',
  PRIMARY KEY (`adoption_id`) USING BTREE,
  UNIQUE INDEX `uk_wo_policy_adoption_command`(`tenant_id`, `command_id`) USING BTREE,
  INDEX `idx_wo_policy_adoption_state`(`tenant_id`, `erp_wo_id`, `status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '原工单策略独立审批采纳账，实际生效由ERP业务事务执行' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wm_work_order_tracking_policy
-- ----------------------------
DROP TABLE IF EXISTS `wm_work_order_tracking_policy`;
CREATE TABLE `wm_work_order_tracking_policy`  (
  `snapshot_id` bigint(20) NOT NULL COMMENT '不可变工单策略记录ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户ID，必须由认证上下文提供',
  `erp_wo_id` bigint(20) NOT NULL COMMENT '真实ERP工单来源ID',
  `material_id` bigint(20) NOT NULL COMMENT '根物料或原组件物料ID',
  `snapshot_version` int(11) NOT NULL COMMENT '策略证据格式版本，不推定历史版本',
  `policy_version` bigint(20) NOT NULL COMMENT '原追踪策略版本',
  `policy_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原追踪策略冻结JSON',
  `policy_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '原策略JSON原始UTF8字节摘要',
  `source_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原工单及完整物料来源范围JSON',
  `source_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '原工单来源JSON原始字节摘要',
  `snapshot_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '同工单整组策略证据摘要',
  `provenance` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'ERP_RELEASE或有明确原证据的SOURCE_POLICY_ADOPTION',
  `evidence_ref` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原release或经批准历史策略凭据引用',
  `frozen_at` datetime(3) NOT NULL COMMENT '原策略证据冻结时点',
  `effective_from` datetime(3) NOT NULL COMMENT '明确原生效切点，不以当前时间补造历史',
  `actor_id` bigint(20) NULL DEFAULT NULL COMMENT '明确采纳操作人；原自动release可空',
  PRIMARY KEY (`snapshot_id`) USING BTREE,
  UNIQUE INDEX `uk_wo_tracking_policy`(`tenant_id`, `erp_wo_id`, `material_id`) USING BTREE,
  INDEX `idx_wo_tracking_policy_material`(`tenant_id`, `material_id`, `erp_wo_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '不可变工单原追踪策略证据，旧工单缺失保持UNKNOWN' ROW_FORMAT = Dynamic;

SET FOREIGN_KEY_CHECKS = 1;
